// RDJ REVERB: native stereo algorithmic reverb for Group Bus and FX Returns.
class RDJReverbProcessor final : public juce::AudioProcessor {
public:
    RDJReverbProcessor()
        : AudioProcessor(BusesProperties().withInput("Input", juce::AudioChannelSet::stereo(), true)
                                           .withOutput("Output", juce::AudioChannelSet::stereo(), true)),
          state(*this, nullptr, "RDJ_REVERB_STATE", createParameters()) {
        roomSize = state.getRawParameterValue("roomSize");
        damping = state.getRawParameterValue("damping");
        wet = state.getRawParameterValue("wet");
        dry = state.getRawParameterValue("dry");
        width = state.getRawParameterValue("width");
        freeze = state.getRawParameterValue("freeze");
        bypass = state.getRawParameterValue("bypass");
        updateParameters();
    }

    static juce::AudioProcessorValueTreeState::ParameterLayout createParameters() {
        juce::AudioProcessorValueTreeState::ParameterLayout layout;
        layout.add(std::make_unique<juce::AudioParameterFloat>(
            juce::ParameterID{"roomSize", 1}, "ROOM SIZE",
            juce::NormalisableRange<float>(0.0f, 1.0f, 0.01f), 0.55f));
        layout.add(std::make_unique<juce::AudioParameterFloat>(
            juce::ParameterID{"damping", 1}, "DAMPING",
            juce::NormalisableRange<float>(0.0f, 1.0f, 0.01f), 0.35f));
        layout.add(std::make_unique<juce::AudioParameterFloat>(
            juce::ParameterID{"wet", 1}, "WET",
            juce::NormalisableRange<float>(0.0f, 1.0f, 0.01f), 0.30f));
        layout.add(std::make_unique<juce::AudioParameterFloat>(
            juce::ParameterID{"dry", 1}, "DRY",
            juce::NormalisableRange<float>(0.0f, 1.0f, 0.01f), 1.0f));
        layout.add(std::make_unique<juce::AudioParameterFloat>(
            juce::ParameterID{"width", 1}, "WIDTH",
            juce::NormalisableRange<float>(0.0f, 1.0f, 0.01f), 1.0f));
        layout.add(std::make_unique<juce::AudioParameterBool>(
            juce::ParameterID{"freeze", 1}, "FREEZE", false));
        layout.add(std::make_unique<juce::AudioParameterBool>(
            juce::ParameterID{"bypass", 1}, "BYPASS", false));
        return layout;
    }

    const juce::String getName() const override { return "RDJ REVERB"; }
    void prepareToPlay(double rate, int) override {
        sampleRate = juce::jmax(8000.0, rate);
        reverb.setSampleRate(sampleRate);
        reverb.reset();
        updateParameters();
    }
    void releaseResources() override { reverb.reset(); }
    bool isBusesLayoutSupported(const BusesLayout& layouts) const override {
        return layouts.getMainInputChannelSet() == juce::AudioChannelSet::stereo()
            && layouts.getMainOutputChannelSet() == juce::AudioChannelSet::stereo();
    }
    void processBlock(juce::AudioBuffer<float>& buffer, juce::MidiBuffer&) override {
        juce::ScopedNoDenormals noDenormals;
        if (bypass->load(std::memory_order_relaxed) >= 0.5f
            || buffer.getNumChannels() < 2)
            return;

        updateParameters();
        reverb.processStereo(buffer.getWritePointer(0), buffer.getWritePointer(1),
                             buffer.getNumSamples());
    }
    void reset() override { reverb.reset(); }
    juce::AudioProcessorEditor* createEditor() override {
        return new juce::GenericAudioProcessorEditor(*this);
    }
    bool hasEditor() const override { return true; }
    bool acceptsMidi() const override { return false; }
    bool producesMidi() const override { return false; }
    bool isMidiEffect() const override { return false; }
    double getTailLengthSeconds() const override { return 8.0; }
    int getNumPrograms() override { return 1; }
    int getCurrentProgram() override { return 0; }
    void setCurrentProgram(int) override {}
    const juce::String getProgramName(int) override { return {}; }
    void changeProgramName(int, const juce::String&) override {}
    void getStateInformation(juce::MemoryBlock& dest) override {
        auto copy = state.copyState();
        std::unique_ptr<juce::XmlElement> xml(copy.createXml());
        copyXmlToBinary(*xml, dest);
    }
    void setStateInformation(const void* data, int size) override {
        std::unique_ptr<juce::XmlElement> xml(getXmlFromBinary(data, size));
        if (xml != nullptr && xml->hasTagName(state.state.getType()))
            state.replaceState(juce::ValueTree::fromXml(*xml));
        updateParameters();
    }

private:
    void updateParameters() {
        juce::Reverb::Parameters params;
        params.roomSize = roomSize->load(std::memory_order_relaxed);
        params.damping = damping->load(std::memory_order_relaxed);
        params.wetLevel = wet->load(std::memory_order_relaxed);
        params.dryLevel = dry->load(std::memory_order_relaxed);
        params.width = width->load(std::memory_order_relaxed);
        params.freezeMode = freeze->load(std::memory_order_relaxed) >= 0.5f ? 1.0f : 0.0f;
        reverb.setParameters(params);
    }

    juce::AudioProcessorValueTreeState state;
    juce::Reverb reverb;
    std::atomic<float>* roomSize = nullptr;
    std::atomic<float>* damping = nullptr;
    std::atomic<float>* wet = nullptr;
    std::atomic<float>* dry = nullptr;
    std::atomic<float>* width = nullptr;
    std::atomic<float>* freeze = nullptr;
    std::atomic<float>* bypass = nullptr;
    double sampleRate = 48000.0;
};


// RDJ GEQ: native 31-band graphic equalizer. No third-party VST dependency.
class RDJGeqProcessor final : public juce::AudioProcessor {
public:
    static constexpr int bandCount = 31;
    static constexpr std::array<double, bandCount> frequencies {{
        20.0, 25.0, 31.5, 40.0, 50.0, 63.0, 80.0, 100.0, 125.0, 160.0,
        200.0, 250.0, 315.0, 400.0, 500.0, 630.0, 800.0, 1000.0, 1250.0,
        1600.0, 2000.0, 2500.0, 3150.0, 4000.0, 5000.0, 6300.0, 8000.0,
        10000.0, 12500.0, 16000.0, 20000.0
    }};

    RDJGeqProcessor()
        : AudioProcessor(BusesProperties().withInput("Input", juce::AudioChannelSet::stereo(), true)
                                           .withOutput("Output", juce::AudioChannelSet::stereo(), true)),
          state(*this, nullptr, "RDJ_GEQ_STATE", createParameters()) {
        for (int i = 0; i < bandCount; ++i)
            gainParams[(size_t)i] = state.getRawParameterValue("band" + juce::String(i));
        bypassParam = state.getRawParameterValue("bypass");
    }

    static juce::AudioProcessorValueTreeState::ParameterLayout createParameters() {
        juce::AudioProcessorValueTreeState::ParameterLayout layout;
        for (int i = 0; i < bandCount; ++i) {
            const auto hz = frequencies[(size_t)i];
            const auto label = hz >= 1000.0 ? juce::String(hz / 1000.0, hz >= 10000.0 ? 0 : 2) + "k"
                                             : juce::String(hz, hz < 100.0 ? 1 : 0);
            layout.add(std::make_unique<juce::AudioParameterFloat>(
                juce::ParameterID { "band" + juce::String(i), 1 },
                label, juce::NormalisableRange<float>(-12.0f, 12.0f, 0.1f), 0.0f));
        }
        layout.add(std::make_unique<juce::AudioParameterBool>(
            juce::ParameterID { "bypass", 1 }, "Bypass", false));
        return layout;
    }

    const juce::String getName() const override { return "RDJ GEQ 31"; }
    void prepareToPlay(double rate, int) override {
        currentRate = juce::jmax(8000.0, rate);
        lastGainDb.fill(std::numeric_limits<double>::quiet_NaN());
        reset();
    }
    void releaseResources() override { reset(); }
    bool isBusesLayoutSupported(const BusesLayout& layouts) const override {
        const auto in = layouts.getMainInputChannelSet();
        const auto out = layouts.getMainOutputChannelSet();
        return in == out && (in == juce::AudioChannelSet::mono() || in == juce::AudioChannelSet::stereo());
    }
    void reset() override {
        for (auto& channel : z1) channel.fill(0.0);
        for (auto& channel : z2) channel.fill(0.0);
    }
    void processBlock(juce::AudioBuffer<float>& buffer, juce::MidiBuffer&) override {
        juce::ScopedNoDenormals noDenormals;
        if (bypassParam != nullptr && bypassParam->load(std::memory_order_relaxed) >= 0.5f)
            return;
        const int channels = juce::jmin(2, buffer.getNumChannels());
        const int samples = buffer.getNumSamples();
        if (channels == 0 || samples == 0) return;

        // Recalculate expensive biquad coefficients only when a control changes.
        // The normal audio path now performs atomic reads and comparisons only.
        for (int band = 0; band < bandCount; ++band) {
            const auto b = (size_t)band;
            const double gainDb = gainParams[b] != nullptr
                ? (double)gainParams[b]->load(std::memory_order_relaxed) : 0.0;
            if (gainDb == lastGainDb[b])
                continue;

            const double A = std::pow(10.0, gainDb / 40.0);
            const double w0 = juce::MathConstants<double>::twoPi
                            * juce::jmin(frequencies[b], currentRate * 0.45) / currentRate;
            const double alpha = std::sin(w0) / (2.0 * 4.318);
            const double cosw = std::cos(w0);
            const double a0 = 1.0 + alpha / A;
            coeffB0[b] = (1.0 + alpha * A) / a0;
            coeffB1[b] = (-2.0 * cosw) / a0;
            coeffB2[b] = (1.0 - alpha * A) / a0;
            coeffA1[b] = (-2.0 * cosw) / a0;
            coeffA2[b] = (1.0 - alpha / A) / a0;
            lastGainDb[b] = gainDb;
        }

        for (int ch = 0; ch < channels; ++ch) {
            auto* data = buffer.getWritePointer(ch);
            for (int band = 0; band < bandCount; ++band) {
                const auto b = (size_t)band;
                const double b0 = coeffB0[b], b1 = coeffB1[b], b2 = coeffB2[b];
                const double a1 = coeffA1[b], a2 = coeffA2[b];
                double s1 = z1[(size_t)ch][b], s2 = z2[(size_t)ch][b];
                for (int n = 0; n < samples; ++n) {
                    const double x = data[n];
                    const double y = b0 * x + s1;
                    s1 = b1 * x - a1 * y + s2;
                    s2 = b2 * x - a2 * y;
                    data[n] = (float)y;
                }
                z1[(size_t)ch][b] = s1;
                z2[(size_t)ch][b] = s2;
            }
        }
    }
    bool acceptsMidi() const override { return false; }
    bool producesMidi() const override { return false; }
    bool isMidiEffect() const override { return false; }
    double getTailLengthSeconds() const override { return 0.0; }
    int getNumPrograms() override { return 1; }
    int getCurrentProgram() override { return 0; }
    void setCurrentProgram(int) override {}
    const juce::String getProgramName(int) override { return "Default"; }
    void changeProgramName(int, const juce::String&) override {}
    bool hasEditor() const override { return true; }
    juce::AudioProcessorEditor* createEditor() override;
    void getStateInformation(juce::MemoryBlock& dest) override {
        auto tree = state.copyState();
        std::unique_ptr<juce::XmlElement> xml(tree.createXml());
        copyXmlToBinary(*xml, dest);
    }
    void setStateInformation(const void* data, int size) override {
        std::unique_ptr<juce::XmlElement> xml(getXmlFromBinary(data, size));
        if (xml != nullptr && xml->hasTagName(state.state.getType()))
            state.replaceState(juce::ValueTree::fromXml(*xml));
    }

    // Public, explicit access for the native editor's APVTS attachments.
    juce::AudioProcessorValueTreeState& getParameterState() noexcept { return state; }

private:
    friend class RDJGeqEditor; // Editor needs APVTS access for slider attachments and reset.
    juce::AudioProcessorValueTreeState state;
    std::array<std::atomic<float>*, bandCount> gainParams {};
    std::atomic<float>* bypassParam = nullptr;
    double currentRate = 48000.0;
    std::array<double, bandCount> coeffB0{}, coeffB1{}, coeffB2{}, coeffA1{}, coeffA2{};
    std::array<double, bandCount> lastGainDb {};
    std::array<std::array<double, bandCount>, 2> z1{}, z2{};
};


// RDJ VITAMIN: five-band native harmonic enhancer inspired by multiband
// parallel enhancement workflows. Original RDJ DSP and parameter model.
class RDJVitaminProcessor final : public juce::AudioProcessor {
public:
    static constexpr int bands = 5;
    static constexpr const char* bandNames[bands] = { "LO", "LOMID", "MID", "HIMID", "HI" };
    RDJVitaminProcessor()
        : AudioProcessor(BusesProperties().withInput("Input", juce::AudioChannelSet::stereo(), true)
                                           .withOutput("Output", juce::AudioChannelSet::stereo(), true)),
          state(*this, nullptr, "RDJ_VITAMIN_STATE", createParameters()) {
        input = param("input"); direct = param("direct"); punch = param("punch");
        output = param("output"); masterWidth = param("widthMaster");
        bypass = param("bypass");
        for (int i = 0; i < bands; ++i) {
            gain[(size_t)i] = param("gain" + juce::String(i));
            width[(size_t)i] = param("width" + juce::String(i));
            solo[(size_t)i] = param("solo" + juce::String(i));
            bandBypass[(size_t)i] = param("bypass" + juce::String(i));
        }
        for (int i = 0; i < 4; ++i) crossover[(size_t)i] = param("xover" + juce::String(i));
    }
    std::atomic<float>* param(const juce::String& id) { return state.getRawParameterValue(id); }

    static juce::AudioProcessorValueTreeState::ParameterLayout createParameters() {
        juce::AudioProcessorValueTreeState::ParameterLayout p;
        auto addFloat = [&p](const char* id, const char* name, float lo, float hi, float def, float step = 0.1f) {
            p.add(std::make_unique<juce::AudioParameterFloat>(
                juce::ParameterID{id, 1}, name, juce::NormalisableRange<float>(lo, hi, step), def));
        };
        auto addBool = [&p](const juce::String& id, const juce::String& name) {
            p.add(std::make_unique<juce::AudioParameterBool>(juce::ParameterID{id, 1}, name, false));
        };
        addFloat("input", "INPUT", -18.0f, 18.0f, 0.0f);
        addFloat("direct", "DIRECT", -48.0f, 0.0f, -48.0f);
        addFloat("punch", "PUNCH", 0.0f, 5.0f, 3.0f, 0.01f);
        addFloat("output", "OUTPUT", -18.0f, 18.0f, 0.0f);
        addFloat("widthMaster", "WIDTH MASTER", 0.0f, 2.0f, 1.0f, 0.01f);
        addFloat("xover0", "XOVER LO", 20.0f, 18000.0f, 90.0f, 1.0f);
        addFloat("xover1", "XOVER LOMID", 20.0f, 18000.0f, 500.0f, 1.0f);
        addFloat("xover2", "XOVER HIMID", 20.0f, 18000.0f, 2594.0f, 1.0f);
        addFloat("xover3", "XOVER HI", 20.0f, 18000.0f, 9310.0f, 1.0f);
        for (int i = 0; i < bands; ++i) {
            addFloat(("gain" + juce::String(i)).toRawUTF8(),
                     (juce::String(bandNames[i]) + " GAIN").toRawUTF8(), 0.0f, 48.0f, 0.0f, 0.1f);
            addFloat(("width" + juce::String(i)).toRawUTF8(),
                     (juce::String(bandNames[i]) + " WIDTH").toRawUTF8(), 0.0f, 3.0f, 1.0f, 0.01f);
            addBool("solo" + juce::String(i), juce::String(bandNames[i]) + " SOLO");
            addBool("bypass" + juce::String(i), juce::String(bandNames[i]) + " BYPASS");
        }
        addBool("bypass", "MASTER BYPASS");
        return p;
    }

    const juce::String getName() const override { return "RDJ VITAMIN"; }
    void prepareToPlay(double rate, int) override { sampleRate = juce::jmax(8000.0, rate); reset(); }
    void releaseResources() override { reset(); }
    bool isBusesLayoutSupported(const BusesLayout& l) const override {
        const auto in = l.getMainInputChannelSet(), out = l.getMainOutputChannelSet();
        return in == out && (in == juce::AudioChannelSet::mono() || in == juce::AudioChannelSet::stereo());
    }
    void reset() override {
        for (auto& c : lpState) c.fill(0.0f);
        envState.fill(0.0f);
    }
    static float softClip(float x, float drive) noexcept {
        const float d = 1.0f + drive * 5.0f;
        const float norm = std::tanh(d);
        return std::tanh(x * d) / juce::jmax(0.001f, norm);
    }
    void processBlock(juce::AudioBuffer<float>& buffer, juce::MidiBuffer&) override {
        juce::ScopedNoDenormals noDenormals;
        if (bypass->load(std::memory_order_relaxed) >= 0.5f) return;
        const int chans = juce::jmin(2, buffer.getNumChannels());
        const int nSamples = buffer.getNumSamples();
        if (chans == 0 || nSamples == 0) return;

        const float inGain = juce::Decibels::decibelsToGain(input->load(std::memory_order_relaxed));
        const float directGain = direct->load(std::memory_order_relaxed) <= -47.9f ? 0.0f
            : juce::Decibels::decibelsToGain(direct->load(std::memory_order_relaxed));
        const float outGain = juce::Decibels::decibelsToGain(output->load(std::memory_order_relaxed));
        const float punchAmt = punch->load(std::memory_order_relaxed) / 5.0f;
        const float masterWidthValue = masterWidth->load(std::memory_order_relaxed);
        std::array<float, 4> alpha {};
        float previous = 0.0f;
        for (int i = 0; i < 4; ++i) {
            float hz = crossover[(size_t)i]->load(std::memory_order_relaxed);
            if (i > 0) hz = juce::jmax(hz, previous + 10.0f);
            if (i < 3) hz = juce::jmin(hz, crossover[(size_t)(i + 1)]->load(std::memory_order_relaxed) - 10.0f);
            hz = juce::jlimit(20.0f, (float)(sampleRate * 0.42), hz);
            alpha[(size_t)i] = 1.0f - std::exp(-juce::MathConstants<float>::twoPi * hz / (float)sampleRate);
            previous = hz;
        }
        bool anySolo = false;
        std::array<float, bands> bandDrive {}, bandScale {}, bandNorm {};
        for (int b = 0; b < bands; ++b) {
            anySolo |= solo[(size_t)b]->load(std::memory_order_relaxed) >= 0.5f;
            bandDrive[(size_t)b] = gain[(size_t)b]->load(std::memory_order_relaxed) / 48.0f;
            bandScale[(size_t)b] = 1.0f + bandDrive[(size_t)b] * 1.5f;
            bandNorm[(size_t)b] = juce::jmax(0.001f,
                std::tanh(1.0f + bandDrive[(size_t)b] * 5.0f));
        }

        auto* left = buffer.getWritePointer(0);
        auto* right = chans > 1 ? buffer.getWritePointer(1) : nullptr;
        for (int n = 0; n < nSamples; ++n) {
            float bandSignal[2][bands] {};
            float dry[2] { left[n] * inGain, right != nullptr ? right[n] * inGain : left[n] * inGain };
            float punchGain[2] {};
            for (int ch = 0; ch < chans; ++ch) {
                auto& states = lpState[(size_t)ch];
                for (int k = 0; k < 4; ++k)
                    states[(size_t)k] += alpha[(size_t)k] * (dry[ch] - states[(size_t)k]);
                const float lp0=states[0], lp1=states[1], lp2=states[2], lp3=states[3];
                bandSignal[ch][0]=lp0;
                bandSignal[ch][1]=lp1-lp0;
                bandSignal[ch][2]=lp2-lp1;
                bandSignal[ch][3]=lp3-lp2;
                bandSignal[ch][4]=dry[ch]-lp3;
                const float magnitude = std::abs(dry[ch]);
                float& env = envState[(size_t)ch];
                env += (magnitude > env ? 0.08f : 0.0025f) * (magnitude - env);
                const float transient = juce::jlimit(0.0f, 2.0f, magnitude - env * 0.65f);
                punchGain[ch] = 1.0f + punchAmt * transient * 0.35f;
            }

            float wet[2] {};
            for (int b = 0; b < bands; ++b) {
                if ((anySolo && solo[(size_t)b]->load(std::memory_order_relaxed) < 0.5f)
                    || bandBypass[(size_t)b]->load(std::memory_order_relaxed) >= 0.5f)
                    continue;
                float bandL = bandSignal[0][b];
                float bandR = chans > 1 ? bandSignal[1][b] : bandL;
                const float mid = 0.5f * (bandL + bandR);
                const float side = 0.5f * (bandL - bandR);
                const float bandWidth = width[(size_t)b]->load(std::memory_order_relaxed) * masterWidthValue;
                bandL = mid + side * bandWidth;
                bandR = mid - side * bandWidth;

                const float drive = bandDrive[(size_t)b];
                const float norm = bandNorm[(size_t)b];
                const float scale = bandScale[(size_t)b];
                const float saturationL = std::tanh(bandL * (1.0f + drive * 5.0f)) / norm;
                wet[0] += saturationL * scale * punchGain[0];
                if (chans > 1) {
                    const float saturationR = std::tanh(bandR * (1.0f + drive * 5.0f)) / norm;
                    wet[1] += saturationR * scale * punchGain[1];
                }
            }
            left[n] = (dry[0] * directGain + wet[0]) * outGain;
            if (right != nullptr) right[n] = (dry[1] * directGain + wet[1]) * outGain;
        }
    }
    bool acceptsMidi() const override { return false; }
    bool producesMidi() const override { return false; }
    bool isMidiEffect() const override { return false; }
    double getTailLengthSeconds() const override { return 0.0; }
    int getNumPrograms() override { return 1; }
    int getCurrentProgram() override { return 0; }
    void setCurrentProgram(int) override {}
    const juce::String getProgramName(int) override { return "Default"; }
    void changeProgramName(int, const juce::String&) override {}
    bool hasEditor() const override { return true; }
    juce::AudioProcessorEditor* createEditor() override;
    void getStateInformation(juce::MemoryBlock& dest) override {
        auto tree = state.copyState();
        std::unique_ptr<juce::XmlElement> xml(tree.createXml());
        copyXmlToBinary(*xml, dest);
    }
    void setStateInformation(const void* data, int size) override {
        std::unique_ptr<juce::XmlElement> xml(getXmlFromBinary(data, size));
        if (xml != nullptr && xml->hasTagName(state.state.getType()))
            state.replaceState(juce::ValueTree::fromXml(*xml));
    }
    juce::AudioProcessorValueTreeState& getParameterState() noexcept { return state; }
private:
    juce::AudioProcessorValueTreeState state;
    std::atomic<float>* input=nullptr; std::atomic<float>* direct=nullptr;
    std::atomic<float>* punch=nullptr; std::atomic<float>* output=nullptr;
    std::atomic<float>* masterWidth=nullptr; std::atomic<float>* bypass=nullptr;
    std::array<std::atomic<float>*, bands> gain{}, width{}, solo{}, bandBypass{};
    std::array<std::atomic<float>*, 4> crossover{};
    double sampleRate=48000.0;
    std::array<std::array<float,4>,2> lpState{};
    std::array<float,2> envState{};
};

// Slim vertical-fader RDJ Vitamin editor with independent per-band controls.
class RDJVitaminFaderLookAndFeel final : public juce::LookAndFeel_V4 {
public:
    void drawLinearSlider(juce::Graphics& g, int x, int y, int width, int height,
                          float sliderPos, float minPos, float maxPos,
                          const juce::Slider::SliderStyle style, juce::Slider& slider) override {
        juce::ignoreUnused(minPos, maxPos, slider);
        if (style != juce::Slider::LinearVertical) {
            juce::LookAndFeel_V4::drawLinearSlider(g, x, y, width, height,
                sliderPos, minPos, maxPos, style, slider);
            return;
        }
        auto r = juce::Rectangle<float>((float)x, (float)y, (float)width, (float)height);
        const float trackW = 4.0f;
        auto track = juce::Rectangle<float>(trackW, juce::jmax(1.0f, r.getHeight() - 12.0f))
                         .withCentre({ r.getCentreX(), r.getCentreY() });
        g.setColour(juce::Colour(0xff111c24));
        g.fillRoundedRectangle(track, 2.0f);
        g.setColour(juce::Colour(0xff19c9ee).withAlpha(0.42f));
        g.fillRoundedRectangle(track.withWidth(1.0f).withX(track.getCentreX() - 0.5f), 1.0f);

        // Narrow silver fader cap with cyan position indicator.
        const float capW = juce::jmin(30.0f, r.getWidth() - 2.0f);
        const float capH = 13.0f;
        auto cap = juce::Rectangle<float>(capW, capH).withCentre(
            { r.getCentreX(), juce::jlimit(r.getY() + capH * 0.5f,
                r.getBottom() - capH * 0.5f, sliderPos) });
        g.setColour(juce::Colour(0x99000000));
        g.fillRoundedRectangle(cap.translated(1.0f, 1.0f), 2.5f);
        g.setGradientFill(juce::ColourGradient(juce::Colour(0xfff3f8fb), cap.getX(), cap.getY(),
            juce::Colour(0xff718896), cap.getX(), cap.getBottom(), false));
        g.fillRoundedRectangle(cap, 2.5f);
        g.setColour(juce::Colour(0xffd8f7ff));
        g.drawRoundedRectangle(cap.reduced(0.5f), 2.5f, 0.8f);
        g.setColour(juce::Colour(0xff12c9ef));
        g.fillRoundedRectangle(cap.withHeight(2.0f).withY(cap.getCentreY() - 1.0f).reduced(4.0f, 0.0f), 1.0f);
        // Three fine grip grooves make the cap read like a physical console fader.
        g.setColour(juce::Colour(0xff657b88));
        for (int k = -1; k <= 1; ++k)
            g.drawHorizontalLine((int)(cap.getCentreY() + k * 2.5f), cap.getX() + 5.0f, cap.getRight() - 5.0f);
    }

    void drawRotarySlider(juce::Graphics& g, int x, int y, int width, int height,
                          float sliderPos, float rotaryStartAngle, float rotaryEndAngle,
                          juce::Slider& slider) override {
        juce::ignoreUnused(slider);
        auto bounds = juce::Rectangle<float>((float)x, (float)y, (float)width, (float)height).reduced(5.0f);
        const float diameter = juce::jmin(bounds.getWidth(), bounds.getHeight()) - 8.0f;
        auto knob = juce::Rectangle<float>(diameter, diameter).withCentre(bounds.getCentre());
        const auto centre = knob.getCentre();
        const float radius = diameter * 0.5f;

        // Tick marks around the metal knob.
        for (int i = 0; i <= 10; ++i) {
            const float t = (float)i / 10.0f;
            const float angle = rotaryStartAngle + t * (rotaryEndAngle - rotaryStartAngle);
            const float r1 = radius + 1.0f;
            const float r2 = radius + (i == 0 || i == 10 ? 7.0f : 4.0f);
            juce::Point<float> p1(centre.x + std::sin(angle) * r1, centre.y - std::cos(angle) * r1);
            juce::Point<float> p2(centre.x + std::sin(angle) * r2, centre.y - std::cos(angle) * r2);
            g.setColour(i == 5 ? juce::Colour(0xff20d9ff) : juce::Colour(0xff8195a1));
            g.drawLine({p1.x,p1.y,p2.x,p2.y}, i == 5 ? 1.8f : 1.0f);
        }

        g.setColour(juce::Colour(0x99000000));
        g.fillEllipse(knob.translated(1.5f, 2.0f));
        g.setGradientFill(juce::ColourGradient(juce::Colour(0xff596d78), knob.getX(), knob.getY(),
            juce::Colour(0xff17242d), knob.getRight(), knob.getBottom(), false));
        g.fillEllipse(knob);
        g.setColour(juce::Colour(0xff879ba6));
        g.drawEllipse(knob.reduced(0.8f), 1.2f);
        g.setColour(juce::Colour(0xff354b57));
        g.drawEllipse(knob.reduced(4.0f), 1.0f);

        const float angle = rotaryStartAngle + sliderPos * (rotaryEndAngle - rotaryStartAngle);
        const float pointerLen = radius * 0.68f;
        juce::Point<float> pointer(centre.x + std::sin(angle) * pointerLen,
                                   centre.y - std::cos(angle) * pointerLen);
        g.setColour(juce::Colour(0xff081117));
        g.drawLine(centre.x + 1.0f, centre.y + 1.0f, pointer.x + 1.0f, pointer.y + 1.0f, 3.5f);
        g.setColour(juce::Colour(0xfff2fbff));
        g.drawLine(centre.x, centre.y, pointer.x, pointer.y, 2.8f);
        g.setColour(juce::Colour(0xff16c9ed));
        g.fillEllipse(juce::Rectangle<float>(5.0f, 5.0f).withCentre(centre));
    }
};

class RDJVitaminEditor final : public juce::AudioProcessorEditor {
public:
    explicit RDJVitaminEditor(RDJVitaminProcessor& p)
        : AudioProcessorEditor(p), processor(p) {
        setSize(820, 570);
        setResizable(true, true);
        setResizeLimits(720, 500, 1150, 760);
        title.setText("RDJ VITAMIN", juce::dontSendNotification);
        title.setFont(juce::Font(23.0f, juce::Font::bold));
        title.setColour(juce::Label::textColourId, juce::Colour(0xff20d9ff));
        addAndMakeVisible(title);
        subtitle.setText("5-BAND HARMONIC ENHANCER", juce::dontSendNotification);
        subtitle.setColour(juce::Label::textColourId, juce::Colour(0xff9db4c2));
        addAndMakeVisible(subtitle);

        masterBypass.setButtonText("MASTER BYPASS");
        addAndMakeVisible(masterBypass);
        masterBypassAttachment = std::make_unique<juce::AudioProcessorValueTreeState::ButtonAttachment>(
            processor.getParameterState(), "bypass", masterBypass);

        const std::array<juce::String, 5> globalIDs { "input", "direct", "punch", "output", "widthMaster" };
        const std::array<juce::String, 5> globalNames { "INPUT", "DIRECT", "PUNCH", "OUTPUT", "WIDTH" };
        for (int i = 0; i < 5; ++i) {
            auto& sl = globalSliders[(size_t)i];
            sl.setSliderStyle(juce::Slider::RotaryHorizontalVerticalDrag);
            sl.setTextBoxStyle(juce::Slider::TextBoxBelow, false, 58, 18);
            sl.setColour(juce::Slider::rotarySliderFillColourId, juce::Colour(0xff16c9ed));
            sl.setColour(juce::Slider::thumbColourId, juce::Colour(0xffeafaff));
            sl.setColour(juce::Slider::textBoxTextColourId, juce::Colours::white);
            sl.setColour(juce::Slider::textBoxBackgroundColourId, juce::Colour(0xff17232d));
            sl.setColour(juce::Slider::textBoxOutlineColourId, juce::Colour(0xff405361));
            addAndMakeVisible(sl);
            globalLabels[(size_t)i].setText(globalNames[(size_t)i], juce::dontSendNotification);
            globalLabels[(size_t)i].setJustificationType(juce::Justification::centred);
            globalLabels[(size_t)i].setColour(juce::Label::textColourId, juce::Colour(0xffd5e4ec));
            addAndMakeVisible(globalLabels[(size_t)i]);
            globalAttachments[(size_t)i] = std::make_unique<juce::AudioProcessorValueTreeState::SliderAttachment>(
                processor.getParameterState(), globalIDs[(size_t)i], sl);
        }

        for (int b = 0; b < 5; ++b) {
            auto& f = gainSliders[(size_t)b];
            f.setLookAndFeel(&faderLook);
            f.setSliderStyle(juce::Slider::LinearVertical);
            f.setTextBoxStyle(juce::Slider::TextBoxBelow, false, 54, 18);
            f.setColour(juce::Slider::textBoxTextColourId, juce::Colours::white);
            f.setColour(juce::Slider::textBoxBackgroundColourId, juce::Colour(0xff17232d));
            f.setColour(juce::Slider::textBoxOutlineColourId, juce::Colour(0xff405361));
            addAndMakeVisible(f);
            gainAttachments[(size_t)b] = std::make_unique<juce::AudioProcessorValueTreeState::SliderAttachment>(
                processor.getParameterState(), "gain" + juce::String(b), f);

            bandLabels[(size_t)b].setText(RDJVitaminProcessor::bandNames[b], juce::dontSendNotification);
            bandLabels[(size_t)b].setJustificationType(juce::Justification::centred);
            bandLabels[(size_t)b].setFont(juce::Font(15.0f, juce::Font::bold));
            bandLabels[(size_t)b].setColour(juce::Label::textColourId, juce::Colour(0xff20d9ff));
            addAndMakeVisible(bandLabels[(size_t)b]);

            widthSliders[(size_t)b].setSliderStyle(juce::Slider::LinearHorizontal);
            widthSliders[(size_t)b].setTextBoxStyle(juce::Slider::TextBoxRight, false, 42, 17);
            widthSliders[(size_t)b].setColour(juce::Slider::trackColourId, juce::Colour(0xff16c9ed));
            widthSliders[(size_t)b].setColour(juce::Slider::thumbColourId, juce::Colour(0xffeafaff));
            addAndMakeVisible(widthSliders[(size_t)b]);
            widthAttachments[(size_t)b] = std::make_unique<juce::AudioProcessorValueTreeState::SliderAttachment>(
                processor.getParameterState(), "width" + juce::String(b), widthSliders[(size_t)b]);

            soloButtons[(size_t)b].setButtonText("SOLO");
            bypassButtons[(size_t)b].setButtonText("BYP");
            addAndMakeVisible(soloButtons[(size_t)b]);
            addAndMakeVisible(bypassButtons[(size_t)b]);
            soloAttachments[(size_t)b] = std::make_unique<juce::AudioProcessorValueTreeState::ButtonAttachment>(
                processor.getParameterState(), "solo" + juce::String(b), soloButtons[(size_t)b]);
            bypassAttachments[(size_t)b] = std::make_unique<juce::AudioProcessorValueTreeState::ButtonAttachment>(
                processor.getParameterState(), "bypass" + juce::String(b), bypassButtons[(size_t)b]);
        }

        for (int i = 0; i < 4; ++i) {
            auto& sl = crossoverSliders[(size_t)i];
            sl.setSliderStyle(juce::Slider::LinearHorizontal);
            sl.setTextBoxStyle(juce::Slider::TextBoxRight, false, 58, 17);
            sl.setColour(juce::Slider::trackColourId, juce::Colour(0xff16c9ed));
            sl.setColour(juce::Slider::thumbColourId, juce::Colour(0xffeafaff));
            addAndMakeVisible(sl);
            crossoverAttachments[(size_t)i] = std::make_unique<juce::AudioProcessorValueTreeState::SliderAttachment>(
                processor.getParameterState(), "xover" + juce::String(i), sl);
            crossoverLabels[(size_t)i].setText("XOVER " + juce::String(i + 1), juce::dontSendNotification);
            crossoverLabels[(size_t)i].setColour(juce::Label::textColourId, juce::Colour(0xffc5d5df));
            addAndMakeVisible(crossoverLabels[(size_t)i]);
        }
    }

    ~RDJVitaminEditor() override {
        for (auto& f : gainSliders) f.setLookAndFeel(nullptr);
        for (auto& f : globalSliders) f.setLookAndFeel(nullptr);
    }

    void paint(juce::Graphics& g) override {
        g.fillAll(juce::Colour(0xff101820));
        auto r = getLocalBounds().toFloat().reduced(8.0f);
        g.setColour(juce::Colour(0xff1c2b36));
        g.fillRoundedRectangle(r, 10.0f);
        g.setColour(juce::Colour(0xff263b49));
        g.fillRoundedRectangle(juce::Rectangle<float>(22.0f, 178.0f, (float)getWidth()-44.0f, 270.0f), 7.0f);
        g.setColour(juce::Colour(0xff496171));
        g.drawHorizontalLine(165, 20.0f, (float)getWidth()-20.0f);
        g.drawHorizontalLine(getHeight()-116, 20.0f, (float)getWidth()-20.0f);
        g.setColour(juce::Colour(0xff8fa9b8));
        g.setFont(11.0f);
        g.drawText("BAND ENHANCEMENT", 30, 170, 200, 16, juce::Justification::left);
        g.drawText("CROSSOVER FREQUENCIES", 30, getHeight()-112, 240, 16, juce::Justification::left);
    }

    void resized() override {
        auto area = getLocalBounds().reduced(22);
        auto header = area.removeFromTop(56);
        title.setBounds(header.removeFromLeft(280));
        subtitle.setBounds(25, 54, 260, 20);
        masterBypass.setBounds(header.removeFromRight(150).reduced(2));
        auto globals = area.removeFromTop(92);
        const int globalW = globals.getWidth() / 5;
        for (int i = 0; i < 5; ++i) {
            auto cell = globals.removeFromLeft(globalW);
            globalLabels[(size_t)i].setBounds(cell.removeFromTop(18));
            globalSliders[(size_t)i].setBounds(cell.reduced(5, 0));
        }
        area.removeFromTop(20);
        auto bandsArea = area.removeFromTop(260);
        const int bandW = bandsArea.getWidth() / 5;
        for (int b = 0; b < 5; ++b) {
            auto cell = bandsArea.removeFromLeft(bandW).reduced(8, 0);
            bandLabels[(size_t)b].setBounds(cell.removeFromTop(22));
            gainSliders[(size_t)b].setBounds(cell.removeFromTop(160).reduced(8, 0));
            widthSliders[(size_t)b].setBounds(cell.removeFromTop(25));
            auto buttons = cell.removeFromTop(24);
            soloButtons[(size_t)b].setBounds(buttons.removeFromLeft(buttons.getWidth()/2).reduced(2));
            bypassButtons[(size_t)b].setBounds(buttons.reduced(2));
        }
        area.removeFromTop(20);
        auto xo = area.removeFromTop(70);
        const int xoW = xo.getWidth()/4;
        for (int i=0;i<4;++i) {
            auto cell=xo.removeFromLeft(xoW);
            crossoverLabels[(size_t)i].setBounds(cell.removeFromTop(18));
            crossoverSliders[(size_t)i].setBounds(cell.reduced(2,0));
        }
    }

private:
    RDJVitaminProcessor& processor;
    RDJVitaminFaderLookAndFeel faderLook;
    juce::Label title, subtitle;
    juce::ToggleButton masterBypass;
    std::array<juce::Slider,5> globalSliders, gainSliders, widthSliders;
    std::array<juce::Label,5> globalLabels, bandLabels;
    std::array<juce::ToggleButton,5> soloButtons, bypassButtons;
    std::array<juce::Slider,4> crossoverSliders;
    std::array<juce::Label,4> crossoverLabels;
    std::array<std::unique_ptr<juce::AudioProcessorValueTreeState::SliderAttachment>,5> globalAttachments, gainAttachments, widthAttachments;
    std::array<std::unique_ptr<juce::AudioProcessorValueTreeState::ButtonAttachment>,5> soloAttachments, bypassAttachments;
    std::array<std::unique_ptr<juce::AudioProcessorValueTreeState::SliderAttachment>,4> crossoverAttachments;
    std::unique_ptr<juce::AudioProcessorValueTreeState::ButtonAttachment> masterBypassAttachment;
};

juce::AudioProcessorEditor* RDJVitaminProcessor::createEditor() {
    return new RDJVitaminEditor(*this);
}


// RDJ LA-2A Native: opto-style leveling compressor inspired by classic optical units.
// This is an original RDJ implementation, not a bit-for-bit Waves CLA-2A model.
class RDJLA2AProcessor final : public juce::AudioProcessor {
public:
    RDJLA2AProcessor()
        : AudioProcessor(BusesProperties().withInput("Input", juce::AudioChannelSet::stereo(), true)
                                           .withOutput("Output", juce::AudioChannelSet::stereo(), true)),
          state(*this, nullptr, "RDJ_LA2A_STATE", createParameters()) {
        peakReduction = raw("peakReduction"); gain = raw("gain"); mode = raw("mode");
        autoMakeup = raw("autoMakeup"); vuMode = raw("vuMode"); analog = raw("analog");
        hiFreq = raw("hiFreq"); mix = raw("mix"); trim = raw("trim"); bypass = raw("bypass");
    }

    static juce::AudioProcessorValueTreeState::ParameterLayout createParameters() {
        juce::AudioProcessorValueTreeState::ParameterLayout p;
        auto addFloat = [&p](const char* id, const char* name, float lo, float hi, float def, float step) {
            p.add(std::make_unique<juce::AudioParameterFloat>(
                juce::ParameterID{id, 1}, name, juce::NormalisableRange<float>(lo, hi, step), def));
        };
        addFloat("peakReduction", "PEAK REDUCTION", 0.0f, 100.0f, 35.0f, 0.1f);
        addFloat("gain", "GAIN", 0.0f, 100.0f, 40.0f, 0.1f);
        p.add(std::make_unique<juce::AudioParameterChoice>(
            juce::ParameterID{"mode", 1}, "MODE", juce::StringArray{"COMPRESS", "LIMIT"}, 0));
        p.add(std::make_unique<juce::AudioParameterBool>(juce::ParameterID{"autoMakeup", 1}, "AUTO MAKEUP", true));
        p.add(std::make_unique<juce::AudioParameterChoice>(
            juce::ParameterID{"vuMode", 1}, "VU DISPLAY", juce::StringArray{"GAIN REDUCTION", "INPUT", "OUTPUT"}, 0));
        p.add(std::make_unique<juce::AudioParameterChoice>(
            juce::ParameterID{"analog", 1}, "ANALOG", juce::StringArray{"50 Hz", "60 Hz", "OFF"}, 2));
        addFloat("hiFreq", "HI FREQ", 0.0f, 100.0f, 0.0f, 0.1f);
        addFloat("mix", "MIX", 0.0f, 100.0f, 100.0f, 0.1f);
        addFloat("trim", "TRIM", -18.0f, 18.0f, 0.0f, 0.1f);
        p.add(std::make_unique<juce::AudioParameterBool>(juce::ParameterID{"bypass", 1}, "BYPASS", false));
        return p;
    }

    std::atomic<float>* raw(const juce::String& id) { return state.getRawParameterValue(id); }
    juce::AudioProcessorValueTreeState& getParameterState() noexcept { return state; }

    const juce::String getName() const override { return "RDJ LA-2A Native"; }
    void prepareToPlay(double sr, int) override {
        sampleRate = juce::jmax(8000.0, sr);
        envelope.fill(0.0f);
        grMeter.store(0.0f); inputMeter.store(0.0f); outputMeter.store(0.0f);
        lowState.fill(0.0f);
    }
    void releaseResources() override {}
    bool isBusesLayoutSupported(const BusesLayout& layouts) const override {
        const auto in = layouts.getMainInputChannelSet();
        const auto out = layouts.getMainOutputChannelSet();
        return in == out && (in == juce::AudioChannelSet::mono() || in == juce::AudioChannelSet::stereo());
    }
    void reset() override {
        envelope.fill(0.0f); lowState.fill(0.0f);
        grMeter.store(0.0f); inputMeter.store(0.0f); outputMeter.store(0.0f);
    }

    void processBlock(juce::AudioBuffer<float>& buffer, juce::MidiBuffer&) override {
        juce::ScopedNoDenormals noDenormals;
        if (bypass->load(std::memory_order_relaxed) >= 0.5f) return;

        const int channels = juce::jmin(2, buffer.getNumChannels());
        const int samples = buffer.getNumSamples();
        if (channels == 0 || samples == 0) return;

        const float reduction = peakReduction->load(std::memory_order_relaxed) / 100.0f;
        const bool limiting = mode->load(std::memory_order_relaxed) >= 0.5f;
        const bool autoGain = autoMakeup->load(std::memory_order_relaxed) >= 0.5f;
        const int analogMode = (int)analog->load(std::memory_order_relaxed);
        const float hi = hiFreq->load(std::memory_order_relaxed) / 100.0f;
        const float wet = mix->load(std::memory_order_relaxed) / 100.0f;
        const float trimGain = juce::Decibels::decibelsToGain(trim->load(std::memory_order_relaxed));
        const float userGain = juce::Decibels::decibelsToGain((gain->load(std::memory_order_relaxed) - 50.0f) * 0.36f);
        const float thresholdDb = -4.0f - reduction * 34.0f;
        const float ratio = limiting ? 10.0f : 3.8f;
        const float attackMs = limiting ? 4.0f : 9.0f;
        const float releaseMs = 85.0f + reduction * 430.0f;
        const float attackCoeff = std::exp(-1.0f / (0.001f * attackMs * (float)sampleRate));
        const float releaseCoeff = std::exp(-1.0f / (0.001f * releaseMs * (float)sampleRate));
        const float makeupDb = autoGain ? reduction * (limiting ? 7.0f : 5.0f) : 0.0f;
        const float makeup = juce::Decibels::decibelsToGain(makeupDb);
        const float saturationDrive = 1.0f + reduction * 0.65f;
        const float saturationNorm = juce::jmax(0.001f, std::tanh(saturationDrive));
        const float hiCoeff = 1.0f - std::exp(-juce::MathConstants<float>::twoPi * 180.0f / (float)sampleRate);

        float peakIn = 0.0f, peakOut = 0.0f, peakGr = 0.0f;
        for (int n = 0; n < samples; ++n) {
            float grSum = 0.0f;
            for (int ch = 0; ch < channels; ++ch) {
                auto* data = buffer.getWritePointer(ch);
                const float dry = data[n];
                const float absIn = std::abs(dry);
                peakIn = juce::jmax(peakIn, absIn);

                // Frequency-weighted optical detector: HI FREQ changes detector emphasis.
                lowState[(size_t)ch] += hiCoeff * (dry - lowState[(size_t)ch]);
                const float highPart = dry - lowState[(size_t)ch];
                const float detector = std::abs(lowState[(size_t)ch] + highPart * (1.0f + hi * 1.8f));

                float& env = envelope[(size_t)ch];
                const float coeff = detector > env ? attackCoeff : releaseCoeff;
                env = coeff * env + (1.0f - coeff) * detector;
                const float levelDb = juce::Decibels::gainToDecibels(env + 1.0e-9f);
                const float overDb = juce::jmax(0.0f, levelDb - thresholdDb);
                const float compressedDb = overDb * (1.0f - 1.0f / ratio);
                const float gainReductionDb = juce::jmin(24.0f, compressedDb);
                const float compGain = juce::Decibels::decibelsToGain(-gainReductionDb);
                grSum += gainReductionDb;
                peakGr = juce::jmax(peakGr, gainReductionDb);

                float wetSignal = dry * compGain * makeup * userGain * trimGain;
                // Gentle transformer/tube-style saturation at higher drive.
                wetSignal = std::tanh(wetSignal * saturationDrive) / saturationNorm;
                // Optional very-low-level mains hum/noise character, disabled by default.
                if (analogMode != 2) {
                    noisePhase += (analogMode == 0 ? 50.0 : 60.0) / sampleRate;
                    if (noisePhase >= 1.0) noisePhase -= 1.0;
                    const float hum = std::sin(noisePhase * juce::MathConstants<float>::twoPi) * 0.000025f;
                    wetSignal += hum;
                }
                data[n] = dry + (wetSignal - dry) * wet;
                peakOut = juce::jmax(peakOut, std::abs(data[n]));
            }
            (void)grSum;
        }

        const float meterSmooth = 0.18f;
        grMeter.store(grMeter.load(std::memory_order_relaxed) * (1.0f - meterSmooth)
                      + peakGr * meterSmooth, std::memory_order_relaxed);
        inputMeter.store(inputMeter.load(std::memory_order_relaxed) * (1.0f - meterSmooth)
                         + peakIn * meterSmooth, std::memory_order_relaxed);
        outputMeter.store(outputMeter.load(std::memory_order_relaxed) * (1.0f - meterSmooth)
                          + peakOut * meterSmooth, std::memory_order_relaxed);
    }

    float getGrMeter() const noexcept { return grMeter.load(std::memory_order_relaxed); }
    float getInputMeter() const noexcept { return inputMeter.load(std::memory_order_relaxed); }
    float getOutputMeter() const noexcept { return outputMeter.load(std::memory_order_relaxed); }

    bool acceptsMidi() const override { return false; }
    bool producesMidi() const override { return false; }
    bool isMidiEffect() const override { return false; }
    double getTailLengthSeconds() const override { return 0.0; }
    int getNumPrograms() override { return 1; }
    int getCurrentProgram() override { return 0; }
    void setCurrentProgram(int) override {}
    const juce::String getProgramName(int) override { return "Default"; }
    void changeProgramName(int, const juce::String&) override {}
    bool hasEditor() const override { return true; }
    juce::AudioProcessorEditor* createEditor() override;
    void getStateInformation(juce::MemoryBlock& dest) override {
        auto tree = state.copyState();
        std::unique_ptr<juce::XmlElement> xml(tree.createXml());
        copyXmlToBinary(*xml, dest);
    }
    void setStateInformation(const void* data, int size) override {
        std::unique_ptr<juce::XmlElement> xml(getXmlFromBinary(data, size));
        if (xml != nullptr && xml->hasTagName(state.state.getType()))
            state.replaceState(juce::ValueTree::fromXml(*xml));
    }

private:
    juce::AudioProcessorValueTreeState state;
    std::atomic<float>* peakReduction = nullptr;
    std::atomic<float>* gain = nullptr;
    std::atomic<float>* mode = nullptr;
    std::atomic<float>* autoMakeup = nullptr;
    std::atomic<float>* vuMode = nullptr;
    std::atomic<float>* analog = nullptr;
    std::atomic<float>* hiFreq = nullptr;
    std::atomic<float>* mix = nullptr;
    std::atomic<float>* trim = nullptr;
    std::atomic<float>* bypass = nullptr;
    std::array<float, 2> envelope{}, lowState{};
    std::atomic<float> grMeter{0.0f}, inputMeter{0.0f}, outputMeter{0.0f};
    double sampleRate = 48000.0;
    double noisePhase = 0.0;
};


class RDJLA2AKnobLookAndFeel final : public juce::LookAndFeel_V4 {
public:
    void drawRotarySlider(juce::Graphics& g, int x, int y, int w, int h, float pos,
                          float start, float end, juce::Slider& slider) override {
        const float side = (float)juce::jmin(w, h);
        const float cx = x + w * 0.5f;
        const float cy = y + side * 0.43f;
        const float r = side * 0.315f;
        const float angle = start + pos * (end - start);

        // Outer shadow and dark knurled bezel.
        g.setColour(juce::Colour(0x88000000));
        g.fillEllipse(cx-r-5.0f, cy-r+5.0f, (r+5.0f)*2.0f, (r+5.0f)*2.0f);
        g.setGradientFill(juce::ColourGradient(juce::Colour(0xff777b7e), cx-r, cy-r,
                                               juce::Colour(0xff080a0c), cx+r, cy+r, true));
        g.fillEllipse(cx-r-2.0f, cy-r-2.0f, (r+2.0f)*2.0f, (r+2.0f)*2.0f);

        // Fine grip notches around the bezel.
        for (int i=0; i<48; ++i) {
            const float a = juce::MathConstants<float>::twoPi * (float)i / 48.0f;
            const float inner = r * 0.91f;
            const float outer = r * ((i%4)==0 ? 1.08f : 1.035f);
            g.setColour((i%4)==0 ? juce::Colour(0xffe1e2df) : juce::Colour(0xff55595b));
            g.drawLine(cx+std::cos(a)*inner, cy+std::sin(a)*inner,
                       cx+std::cos(a)*outer, cy+std::sin(a)*outer,
                       (i%4)==0 ? 1.5f : 0.8f);
        }

        // Chrome face with radial brushed-metal gradient.
        const float face = r * 0.82f;
        g.setGradientFill(juce::ColourGradient(juce::Colour(0xfff8f8f5), cx-face*0.48f, cy-face,
                                               juce::Colour(0xff686e72), cx+face, cy+face, true));
        g.fillEllipse(cx-face, cy-face, face*2.0f, face*2.0f);
        g.setColour(juce::Colour(0xffd5d7d6));
        g.drawEllipse(cx-face+1.0f, cy-face+1.0f, face*2.0f-2.0f, face*2.0f-2.0f, 1.0f);

        // Radial brushed highlights and concentric machining rings.
        for (int i=0; i<28; ++i) {
            const float a = juce::MathConstants<float>::twoPi * (float)i / 28.0f;
            g.setColour(juce::Colour(0x24ffffff));
            g.drawLine(cx+std::cos(a)*face*0.16f, cy+std::sin(a)*face*0.16f,
                       cx+std::cos(a)*face*0.94f, cy+std::sin(a)*face*0.94f, 0.55f);
        }
        for (int k=1; k<=3; ++k) {
            const float rr = face * (0.28f + 0.18f*(float)k);
            g.setColour(juce::Colour(0x5570787c));
            g.drawEllipse(cx-rr, cy-rr, rr*2.0f, rr*2.0f, 0.65f);
        }

        // High-contrast scale: major ticks plus numeric markers.
        const auto minV = slider.getMinimum();
        const auto maxV = slider.getMaximum();
        for (int i=0; i<=10; ++i) {
            const float t = (float)i / 10.0f;
            const float a = start + t*(end-start);
            const float r1 = r*1.10f;
            const float r2 = r*((i%2)==0 ? 1.24f : 1.16f);
            g.setColour(t <= pos ? juce::Colour(0xffc52e27) : juce::Colour(0xff292d30));
            g.drawLine(cx+std::cos(a)*r1, cy+std::sin(a)*r1,
                       cx+std::cos(a)*r2, cy+std::sin(a)*r2, (i%2)==0 ? 1.8f : 1.0f);

        }

        // Bright red/orange pointer with a dark edge and chrome centre cap.
        const float pointerR = face*0.82f;
        const float px = cx + std::cos(angle)*pointerR;
        const float py = cy + std::sin(angle)*pointerR;
        g.setColour(juce::Colour(0xff25282a));
        g.drawLine(cx+std::cos(angle)*face*0.12f, cy+std::sin(angle)*face*0.12f,
                   px, py, 5.0f);
        g.setColour(juce::Colour(0xffc52e27));
        g.drawLine(cx+std::cos(angle)*face*0.14f, cy+std::sin(angle)*face*0.14f,
                   px, py, 2.2f);
        g.setGradientFill(juce::ColourGradient(juce::Colour(0xffffffff), cx-2.5f, cy-2.5f,
                                               juce::Colour(0xff6c7073), cx+2.5f, cy+2.5f, true));
        g.fillEllipse(cx-3.0f, cy-3.0f, 6.0f, 6.0f);
    }
};

class RDJLA2AEditor final : public juce::AudioProcessorEditor, private juce::Timer {
public:
    explicit RDJLA2AEditor(RDJLA2AProcessor& p)
        : AudioProcessorEditor(p), processor(p), state(p.getParameterState()), vu(p) {
        setSize(1200, 660);
        setResizable(true, true);
        setResizeLimits(1120, 620, 1500, 900);

        title.setText("RDJ  LA-2A   |   OPTO LEVELING AMPLIFIER", juce::dontSendNotification);
        title.setFont(juce::Font(juce::FontOptions(23.0f).withStyle("Bold")));
        title.setColour(juce::Label::textColourId, juce::Colour(0xff282828));
        addAndMakeVisible(title);

        addAndMakeVisible(vu);

        auto setupKnob = [this](juce::Slider& s, juce::Label& l, const juce::String& text,
                                const juce::String& id, float lo, float hi, float def) {
            l.setText(text, juce::dontSendNotification);
            l.setJustificationType(juce::Justification::centred);
            l.setFont(juce::Font(juce::FontOptions(12.0f).withStyle("Bold")));
            l.setColour(juce::Label::textColourId, juce::Colour(0xff343434));
            addAndMakeVisible(l);
            s.setSliderStyle(juce::Slider::RotaryHorizontalVerticalDrag);
            s.setLookAndFeel(&knobLookAndFeel);
            s.setRotaryParameters(juce::MathConstants<float>::pi * 1.25f,
                                  juce::MathConstants<float>::pi * 2.75f, true);
            s.setTextBoxStyle(juce::Slider::TextBoxBelow, false, 58, 18);
            s.setRange(lo, hi, 0.1);
            s.setValue(def);
            s.setColour(juce::Slider::rotarySliderFillColourId, juce::Colour(0xff8e8e8e));
            s.setColour(juce::Slider::rotarySliderOutlineColourId, juce::Colour(0xff383838));
            s.setColour(juce::Slider::thumbColourId, juce::Colour(0xfff5f5f5));
            s.setColour(juce::Slider::textBoxTextColourId, juce::Colour(0xff222222));
            s.setColour(juce::Slider::textBoxBackgroundColourId, juce::Colour(0xffd6d6d6));
            s.setColour(juce::Slider::textBoxOutlineColourId, juce::Colour(0xff777777));
            addAndMakeVisible(s);
            sliderAttachments.push_back(std::make_unique<juce::AudioProcessorValueTreeState::SliderAttachment>(state, id, s));
        };

        setupKnob(gainKnob, gainLabel, "GAIN", "gain", 0, 100, 40);
        setupKnob(reductionKnob, reductionLabel, "PEAK REDUCTION", "peakReduction", 0, 100, 35);
        setupKnob(hiFreqKnob, hiFreqLabel, "HI FREQ", "hiFreq", 0, 100, 0);
        setupKnob(mixKnob, mixLabel, "MIX", "mix", 0, 100, 100);
        setupKnob(trimKnob, trimLabel, "TRIM", "trim", -18, 18, 0);

        modeBox.addItem("COMPRESS", 1);
        modeBox.addItem("LIMIT", 2);
        addAndMakeVisible(modeBox);
        comboAttachments.push_back(std::make_unique<juce::AudioProcessorValueTreeState::ComboBoxAttachment>(state, "mode", modeBox));

        vuBox.addItem("GR", 1); vuBox.addItem("INPUT", 2); vuBox.addItem("OUTPUT", 3);
        addAndMakeVisible(vuBox);
        comboAttachments.push_back(std::make_unique<juce::AudioProcessorValueTreeState::ComboBoxAttachment>(state, "vuMode", vuBox));

        analogBox.addItem("50 Hz", 1); analogBox.addItem("60 Hz", 2); analogBox.addItem("OFF", 3);
        addAndMakeVisible(analogBox);
        comboAttachments.push_back(std::make_unique<juce::AudioProcessorValueTreeState::ComboBoxAttachment>(state, "analog", analogBox));

        autoMakeup.setButtonText("AUTO MAKEUP");
        addAndMakeVisible(autoMakeup);
        buttonAttachments.push_back(std::make_unique<juce::AudioProcessorValueTreeState::ButtonAttachment>(state, "autoMakeup", autoMakeup));
        bypass.setButtonText("BYPASS");
        addAndMakeVisible(bypass);
        buttonAttachments.push_back(std::make_unique<juce::AudioProcessorValueTreeState::ButtonAttachment>(state, "bypass", bypass));

        startTimerHz(20);
    }

    ~RDJLA2AEditor() override {
        stopTimer();
        gainKnob.setLookAndFeel(nullptr);
        reductionKnob.setLookAndFeel(nullptr);
        hiFreqKnob.setLookAndFeel(nullptr);
        mixKnob.setLookAndFeel(nullptr);
        trimKnob.setLookAndFeel(nullptr);
    }

    void paint(juce::Graphics& g) override {
        auto bounds = getLocalBounds().toFloat();
        g.fillAll(juce::Colour(0xff111416));
        auto frame = bounds.reduced(8.0f);
        g.setGradientFill(juce::ColourGradient(juce::Colour(0xff5d6265), frame.getX(), frame.getY(),
                                               juce::Colour(0xff16191b), frame.getX(), frame.getBottom(), false));
        g.fillRoundedRectangle(frame, 12.0f);

        auto plate = frame.reduced(8.0f);
        plate.removeFromBottom(148.0f);
        g.setGradientFill(juce::ColourGradient(juce::Colour(0xfffffdf8), plate.getX(), plate.getY(),
                                               juce::Colour(0xffb8b8b5), plate.getX(), plate.getBottom(), false));
        g.fillRoundedRectangle(plate, 8.0f);
        g.saveState();
        g.reduceClipRegion(plate.toNearestInt().reduced(3));
        for (int y=(int)plate.getY()+2; y<(int)plate.getBottom(); y+=2) {
            g.setColour(juce::Colours::white.withAlpha((y%4==0)?0.055f:0.025f));
            g.drawHorizontalLine(y, plate.getX()+2.0f, plate.getRight()-2.0f);
        }
        g.restoreState();

        auto lower = frame.reduced(8.0f);
        lower.removeFromTop(frame.getHeight()-148.0f);
        g.setGradientFill(juce::ColourGradient(juce::Colour(0xff303235), lower.getX(), lower.getY(),
                                               juce::Colour(0xff090b0d), lower.getX(), lower.getBottom(), false));
        g.fillRoundedRectangle(lower, 8.0f);
        g.setColour(juce::Colour(0xffa9abad));
        g.drawHorizontalLine((int)lower.getY(), lower.getX()+8.0f, lower.getRight()-8.0f);

        // Brushed-metal panel fasteners.
        auto screw = [&g](float x, float y) {
            g.setColour(juce::Colour(0xff202326)); g.fillEllipse(x-8,y-8,16,16);
            g.setColour(juce::Colour(0xffc7c8c8)); g.drawEllipse(x-6.5f,y-6.5f,13,13,1.1f);
            g.setColour(juce::Colour(0xff303437)); g.drawLine(x-3.5f,y-3.5f,x+3.5f,y+3.5f,1.3f);
        };
        screw(frame.getX()+16, frame.getY()+16);
        screw(frame.getRight()-16, frame.getY()+16);
        screw(frame.getX()+16, frame.getBottom()-16);
        screw(frame.getRight()-16, frame.getBottom()-16);

    }

    void resized() override {
        auto area = getLocalBounds().reduced(18);
        auto header = area.removeFromTop(58);
        title.setBounds(header.removeFromLeft((int)(getWidth()*0.43f)));
        bypass.setBounds(header.removeFromRight(112).reduced(2, 12));
        vuBox.setBounds(header.removeFromRight(132).reduced(2, 9));
        modeBox.setBounds(header.removeFromRight(164).reduced(2, 9));
        area.removeFromTop(8);

        // Keep the upper controls in three non-overlapping columns.
        const int footerHeight = 166;
        auto footer = area.removeFromBottom(footerHeight);
        area.removeFromBottom(8);
        auto main = area;
        const int sideW = juce::jlimit(250, 300, main.getWidth() / 4);
        const int autoW = 116;
        const int vuW = juce::jmin(350, main.getWidth() - sideW * 2 - autoW - 34);
        const int vuH = juce::jmin(210, main.getHeight() - 72);

        gainLabel.setBounds(main.getX() + 4, main.getY() + 4, sideW - 8, 24);
        gainKnob.setBounds(main.getX() + 8, main.getY() + 30, sideW - 16, main.getHeight() - 34);

        reductionLabel.setBounds(main.getRight() - sideW - autoW, main.getY() + 4,
                                 sideW - 8, 24);
        reductionKnob.setBounds(main.getRight() - sideW - autoW + 4, main.getY() + 30,
                                sideW - 16, main.getHeight() - 34);
        autoMakeup.setBounds(main.getRight() - autoW, main.getCentreY() - 24, autoW, 48);

        vu.setBounds(main.getCentreX() - vuW / 2, main.getY() + 34, vuW, vuH);

        // Lower strip: analog selector plus three equally sized control cells.
        auto analogArea = footer.removeFromLeft(juce::jlimit(250, 310, footer.getWidth() / 4));
        analogBox.setBounds(analogArea.reduced(8, 38));
        const int cellW = footer.getWidth() / 3;
        auto placeCell = [](juce::Rectangle<int> cell, juce::Label& label, juce::Slider& slider) {
            label.setBounds(cell.removeFromTop(24));
            slider.setBounds(cell.reduced(12, 0));
        };
        auto cell1 = footer.removeFromLeft(cellW);
        auto cell2 = footer.removeFromLeft(cellW);
        auto cell3 = footer;
        placeCell(cell1, hiFreqLabel, hiFreqKnob);
        placeCell(cell2, mixLabel, mixKnob);
        placeCell(cell3, trimLabel, trimKnob);
    }

private:
    class VUMeter final : public juce::Component {
    public:
        explicit VUMeter(RDJLA2AProcessor& p) : processor(p) {}
        void paint(juce::Graphics& g) override {
            auto r = getLocalBounds().toFloat();
            g.setColour(juce::Colour(0xff17191b)); g.fillRoundedRectangle(r, 7.0f);
            auto dial = r.reduced(7.0f);
            g.setGradientFill(juce::ColourGradient(juce::Colour(0xffffe8a8), dial.getX(), dial.getY(),
                                                   juce::Colour(0xffc8ad70), dial.getX(), dial.getBottom(), false));
            g.fillRoundedRectangle(dial, 3.0f);
            g.setColour(juce::Colour(0xff38342b));
            g.setFont(juce::Font(juce::FontOptions(10.0f).withStyle("Bold")));
            g.drawText("VU  •  GAIN REDUCTION", dial.toNearestInt().reduced(4).removeFromTop(16), juce::Justification::centred);
            const float centreX = r.getCentreX(), pivotY = r.getBottom() - 13.0f;
            const float radius = juce::jmin(r.getWidth() * 0.40f, r.getHeight() * 0.62f);
            for (int i = 0; i <= 10; ++i) {
                const float t = (float)i / 10.0f;
                const float angle = juce::MathConstants<float>::pi * (1.15f + t * 0.70f);
                const float x1 = centreX + std::cos(angle) * (radius - 8.0f);
                const float y1 = pivotY + std::sin(angle) * (radius - 8.0f);
                const float x2 = centreX + std::cos(angle) * radius;
                const float y2 = pivotY + std::sin(angle) * radius;
                g.drawLine(x1, y1, x2, y2, 1.0f);
                g.drawText(juce::String(i * 3), x2 - 9, y2 - 11, 18, 10, juce::Justification::centred);
            }
            const float gr = juce::jlimit(0.0f, 30.0f, processor.getGrMeter());
            const float angle = juce::MathConstants<float>::pi * (1.15f + (gr / 30.0f) * 0.70f);
            g.setColour(juce::Colour(0xffb52e22));
            g.drawLine(centreX, pivotY, centreX + std::cos(angle) * (radius - 13.0f),
                       pivotY + std::sin(angle) * (radius - 13.0f), 2.0f);
            g.setColour(juce::Colour(0xff38342b)); g.fillEllipse(centreX - 4, pivotY - 4, 8, 8);
        }
    private:
        RDJLA2AProcessor& processor;
    };

    void timerCallback() override { vu.repaint(); }

    RDJLA2AProcessor& processor;
    juce::AudioProcessorValueTreeState& state;
    RDJLA2AKnobLookAndFeel knobLookAndFeel;
    juce::Label title, gainLabel, reductionLabel, hiFreqLabel, mixLabel, trimLabel;
    juce::Slider gainKnob, reductionKnob, hiFreqKnob, mixKnob, trimKnob;
    juce::ComboBox modeBox, vuBox, analogBox;
    juce::ToggleButton autoMakeup, bypass;
    VUMeter vu;
    std::vector<std::unique_ptr<juce::AudioProcessorValueTreeState::SliderAttachment>> sliderAttachments;
    std::vector<std::unique_ptr<juce::AudioProcessorValueTreeState::ComboBoxAttachment>> comboAttachments;
    std::vector<std::unique_ptr<juce::AudioProcessorValueTreeState::ButtonAttachment>> buttonAttachments;
};

juce::AudioProcessorEditor* RDJLA2AProcessor::createEditor() { return new RDJLA2AEditor(*this); }


// RDJ F6: six-band dynamic parametric equalizer (native JUCE processor).
// Original implementation using per-band peaking EQ and envelope-controlled gain.
class RDJF6Processor final : public juce::AudioProcessor {
public:
    static constexpr int bandCount = 6;
    struct Biquad {
        float b0=1.0f, b1=0.0f, b2=0.0f, a1=0.0f, a2=0.0f;
        float z1=0.0f, z2=0.0f;
        void reset() noexcept { z1=z2=0.0f; }
        float process(float x) noexcept {
            const float y = b0*x + z1;
            z1 = b1*x - a1*y + z2;
            z2 = b2*x - a2*y;
            return y;
        }
        void setPeak(double sr, float freq, float q, float gainDb) noexcept {
            const double f = juce::jlimit(20.0, sr*0.45, (double)freq);
            const double A = std::pow(10.0, (double)gainDb / 40.0);
            const double w = juce::MathConstants<double>::twoPi * f / sr;
            const double c = std::cos(w), sn = std::sin(w);
            const double alpha = sn / (2.0 * juce::jmax(0.1f, q));
            const double a0 = 1.0 + alpha / A;
            b0=(float)((1.0+alpha*A)/a0); b1=(float)((-2.0*c)/a0); b2=(float)((1.0-alpha*A)/a0);
            a1=(float)((-2.0*c)/a0); a2=(float)((1.0-alpha/A)/a0);
        }
        void setBandPass(double sr, float freq, float q) noexcept {
            const double f=juce::jlimit(20.0,sr*0.45,(double)freq);
            const double w=juce::MathConstants<double>::twoPi*f/sr, c=std::cos(w), sn=std::sin(w);
            const double alpha=sn/(2.0*juce::jmax(0.1f,q)), a0=1.0+alpha;
            b0=(float)(alpha/a0); b1=0.0f; b2=(float)(-alpha/a0);
            a1=(float)((-2.0*c)/a0); a2=(float)((1.0-alpha)/a0);
        }
        void setHighPass(double sr, float freq, double sectionQ) noexcept {
            const double f=juce::jlimit(10.0,sr*0.475,(double)freq);
            const double w=juce::MathConstants<double>::twoPi*f/sr;
            const double c=std::cos(w), sn=std::sin(w);
            const double alpha=sn/(2.0*juce::jmax(0.1,sectionQ)), a0=1.0+alpha;
            b0=(float)(((1.0+c)*0.5)/a0); b1=(float)(-(1.0+c)/a0);
            b2=b0; a1=(float)((-2.0*c)/a0); a2=(float)((1.0-alpha)/a0);
        }
        void setLowPass(double sr, float freq, double sectionQ) noexcept {
            const double f=juce::jlimit(10.0,sr*0.475,(double)freq);
            const double w=juce::MathConstants<double>::twoPi*f/sr;
            const double c=std::cos(w), sn=std::sin(w);
            const double alpha=sn/(2.0*juce::jmax(0.1,sectionQ)), a0=1.0+alpha;
            b0=(float)(((1.0-c)*0.5)/a0); b1=(float)((1.0-c)/a0);
            b2=b0; a1=(float)((-2.0*c)/a0); a2=(float)((1.0-alpha)/a0);
        }
    };
    RDJF6Processor()
        : AudioProcessor(BusesProperties().withInput("Input",juce::AudioChannelSet::stereo(),true)
                                           .withOutput("Output",juce::AudioChannelSet::stereo(),true)),
          state(*this,nullptr,"RDJ_F6_STATE",createParameters()) {
        mix=param("mix"); bypass=param("bypass");
        hpEnable=param("hpf_enable"); hpFreq=param("hpf_freq"); hpSlope=param("hpf_slope");
        lpEnable=param("lpf_enable"); lpFreq=param("lpf_freq"); lpSlope=param("lpf_slope");
        for(int b=0;b<bandCount;++b) {
            const auto n=juce::String(b);
            freq[(size_t)b]=param("freq"+n); q[(size_t)b]=param("q"+n);
            gain[(size_t)b]=param("gain"+n); range[(size_t)b]=param("range"+n);
            threshold[(size_t)b]=param("threshold"+n); attack[(size_t)b]=param("attack"+n);
            release[(size_t)b]=param("release"+n); enabled[(size_t)b]=param("enable"+n);
        }
    }
    std::atomic<float>* param(const juce::String& id){return state.getRawParameterValue(id);}
    static juce::AudioProcessorValueTreeState::ParameterLayout createParameters(){
        juce::AudioProcessorValueTreeState::ParameterLayout p;
        p.add(std::make_unique<juce::AudioParameterFloat>(juce::ParameterID{"mix",1},"GLOBAL MIX",juce::NormalisableRange<float>(0,100,0.1f),100));
        p.add(std::make_unique<juce::AudioParameterBool>(juce::ParameterID{"bypass",1},"MASTER BYPASS",false));
        p.add(std::make_unique<juce::AudioParameterBool>(juce::ParameterID{"hpf_enable",1},"HIGH PASS ENABLE",false));
        p.add(std::make_unique<juce::AudioParameterFloat>(juce::ParameterID{"hpf_freq",1},"HIGH PASS FREQ",
            juce::NormalisableRange<float>(20.0f,2000.0f,1.0f,0.35f),80.0f));
        p.add(std::make_unique<juce::AudioParameterChoice>(juce::ParameterID{"hpf_slope",1},
            "HIGH PASS SLOPE",juce::StringArray{"12 dB/oct","24 dB/oct","36 dB/oct","48 dB/oct"},1));
        p.add(std::make_unique<juce::AudioParameterBool>(juce::ParameterID{"lpf_enable",1},"LOW PASS ENABLE",false));
        p.add(std::make_unique<juce::AudioParameterFloat>(juce::ParameterID{"lpf_freq",1},"LOW PASS FREQ",
            juce::NormalisableRange<float>(1000.0f,20000.0f,1.0f,0.35f),18000.0f));
        p.add(std::make_unique<juce::AudioParameterChoice>(juce::ParameterID{"lpf_slope",1},
            "LOW PASS SLOPE",juce::StringArray{"12 dB/oct","24 dB/oct","36 dB/oct","48 dB/oct"},1));
        const float defaults[6]={80,250,700,1800,5000,12000};
        for(int b=0;b<bandCount;++b){
            const auto n=juce::String(b);
            auto add=[&](const juce::String& id,const juce::String& name,float lo,float hi,float def,float step){
                p.add(std::make_unique<juce::AudioParameterFloat>(juce::ParameterID{id,1},name,juce::NormalisableRange<float>(lo,hi,step),def));
            };
            add("freq"+n,"B"+n+" FREQ",20,20000,defaults[b],1);
            add("q"+n,"B"+n+" Q",0.1f,18.0f,1.0f,0.01f);
            add("gain"+n,"B"+n+" GAIN",-18,18,0,0.1f);
            add("range"+n,"B"+n+" RANGE",-18,0,-6,0.1f);
            add("threshold"+n,"B"+n+" THRESHOLD",-60,0,-24,0.1f);
            add("attack"+n,"B"+n+" ATTACK",0.1f,100,10,0.1f);
            add("release"+n,"B"+n+" RELEASE",5,500,100,0.1f);
            p.add(std::make_unique<juce::AudioParameterBool>(juce::ParameterID{"enable"+n,1},"B"+n+" ENABLE",true));
        }
        return p;
    }
    const juce::String getName()const override{return "RDJ F6";}
    void prepareToPlay(double sr,int)override{sampleRate=juce::jmax(8000.0,sr);reset();updateCoefficients();}
    void releaseResources()override{reset();}
    bool isBusesLayoutSupported(const BusesLayout& l)const override{
        auto i=l.getMainInputChannelSet(),o=l.getMainOutputChannelSet();
        return i==o&&(i==juce::AudioChannelSet::mono()||i==juce::AudioChannelSet::stereo());
    }
    void reset()override{
        for(auto& ch:eqFilters)for(auto& f:ch)f.reset();
        for(auto& ch:detFilters)for(auto& f:ch)f.reset();
        for(auto& ch:highPassFilters)for(auto& f:ch)f.reset();
        for(auto& ch:lowPassFilters)for(auto& f:ch)f.reset();
        for(auto& ch:envelopePower)ch.fill(0.0f);
        for(auto& ch:dynamicGainDb)ch.fill(0.0f);
    }
    // Four cascaded sections provide genuine 12/24/36/48 dB-per-octave
    // Butterworth cuts. Q values are the pole-pair Qs for each order.
    static constexpr double butterworthQ[4][4] = {
        {0.7071067812, 0.7071067812, 0.7071067812, 0.7071067812},
        {1.306562965, 0.5411961001, 0.7071067812, 0.7071067812},
        {1.931851653, 0.7071067812, 0.5176380902, 0.7071067812},
        {2.562915448, 0.9009688679, 0.6013448872, 0.5097955791}
    };
    void updateCoefficients() noexcept {
        const float hpf=hpFreq->load(std::memory_order_relaxed);
        const float lpf=lpFreq->load(std::memory_order_relaxed);
        const int hpOrder=juce::jlimit(0,3,(int)std::lround(hpSlope->load(std::memory_order_relaxed)))+1;
        const int lpOrder=juce::jlimit(0,3,(int)std::lround(lpSlope->load(std::memory_order_relaxed)))+1;
        for(int ch=0;ch<2;++ch) {
            for(int stage=0;stage<4;++stage) {
                const double hq=butterworthQ[(size_t)(hpOrder-1)][(size_t)stage];
                const double lq=butterworthQ[(size_t)(lpOrder-1)][(size_t)stage];
                highPassFilters[(size_t)ch][(size_t)stage].setHighPass(sampleRate,hpf,hq);
                lowPassFilters[(size_t)ch][(size_t)stage].setLowPass(sampleRate,lpf,lq);
            }
        }
        for(int b=0;b<bandCount;++b){
            const float f=freq[(size_t)b]->load(std::memory_order_relaxed);
            const float qq=q[(size_t)b]->load(std::memory_order_relaxed);
            const float g=gain[(size_t)b]->load(std::memory_order_relaxed);
            for(int ch=0;ch<2;++ch){
                const float dynamicDb=dynamicGainDb[(size_t)ch][(size_t)b];
                eqFilters[(size_t)ch][(size_t)b].setPeak(sampleRate,f,qq,g+dynamicDb);
                detFilters[(size_t)ch][(size_t)b].setBandPass(sampleRate,f,qq);
            }
            attackCoeff[(size_t)b]=std::exp(-1.0f/(0.001f*attack[(size_t)b]->load(std::memory_order_relaxed)*(float)sampleRate));
            releaseCoeff[(size_t)b]=std::exp(-1.0f/(0.001f*release[(size_t)b]->load(std::memory_order_relaxed)*(float)sampleRate));
        }
    }
    void processBlock(juce::AudioBuffer<float>& buffer,juce::MidiBuffer&)override{
        juce::ScopedNoDenormals noDenormals;
        if(bypass->load(std::memory_order_relaxed)>=0.5f)return;
        updateCoefficients();
        const int chans=juce::jmin(2,buffer.getNumChannels()), samples=buffer.getNumSamples();
        const float wet=mix->load(std::memory_order_relaxed)*0.01f;
        const bool useHpf=hpEnable->load(std::memory_order_relaxed)>=0.5f;
        const bool useLpf=lpEnable->load(std::memory_order_relaxed)>=0.5f;
        const int hpStages=juce::jlimit(1,4,(int)std::lround(hpSlope->load(std::memory_order_relaxed))+1);
        const int lpStages=juce::jlimit(1,4,(int)std::lround(lpSlope->load(std::memory_order_relaxed))+1);
        for(int ch=0;ch<chans;++ch){
            auto* d=buffer.getWritePointer(ch);
            for(int n=0;n<samples;++n){
                const float originalDry=d[n];
                float processed=originalDry;
                if(useHpf) for(int s=0;s<hpStages;++s)
                    processed=highPassFilters[(size_t)ch][(size_t)s].process(processed);
                if(useLpf) for(int s=0;s<lpStages;++s)
                    processed=lowPassFilters[(size_t)ch][(size_t)s].process(processed);

                // The six EQ bands are cascaded, matching the summed dB response
                // shown by the graph. Each detector listens to the signal at its
                // own point in the chain, not to a shared pre-EQ signal.
                for(int b=0;b<bandCount;++b){
                    if(enabled[(size_t)b]->load(std::memory_order_relaxed)<0.5f)continue;
                    const size_t bi=(size_t)b, ci=(size_t)ch;
                    const float detector=detFilters[ci][bi].process(processed);
                    float& power=envelopePower[ci][bi];
                    const float detectorPower=detector*detector;
                    const float coeff=detectorPower>power?attackCoeff[bi]:releaseCoeff[bi];
                    power=coeff*power+(1.0f-coeff)*detectorPower;
                    const float levelDb=juce::Decibels::gainToDecibels(std::sqrt(juce::jmax(1.0e-12f,power)));
                    const float over=levelDb-threshold[bi]->load(std::memory_order_relaxed);
                    const float maxRange=range[bi]->load(std::memory_order_relaxed);
                    // Soft 6 dB knee, then a bounded range-controlled dynamic
                    // gain. Negative range attenuates; positive range can boost.
                    const float knee=6.0f;
                    const float amount=over<=-knee*0.5f?0.0f:
                        over>=knee*0.5f?over:((over+knee*0.5f)*(over+knee*0.5f))/(2.0f*knee);
                    const float targetDynDb=maxRange*juce::jlimit(0.0f,1.0f,amount/18.0f);
                    float& dynDb=dynamicGainDb[ci][bi];
                    dynDb += (targetDynDb-dynDb)*0.125f;
                    // Coefficients are refreshed every 8 samples to keep dynamic
                    // gain responsive without recalculating trigonometry per sample.
                    if((n&7)==0){
                        eqFilters[ci][bi].setPeak(sampleRate,
                            freq[bi]->load(std::memory_order_relaxed),
                            q[bi]->load(std::memory_order_relaxed),
                            gain[bi]->load(std::memory_order_relaxed)+dynDb);
                    }
                    processed=eqFilters[ci][bi].process(processed);
                }
                d[n]=originalDry+(processed-originalDry)*wet;
            }
        }
    }
    bool acceptsMidi()const override{return false;} bool producesMidi()const override{return false;}
    bool isMidiEffect()const override{return false;} double getTailLengthSeconds()const override{return 0.0;}
    int getNumPrograms()override{return 1;} int getCurrentProgram()override{return 0;}
    void setCurrentProgram(int)override{} const juce::String getProgramName(int)override{return "Default";}
    void changeProgramName(int,const juce::String&)override{}
    bool hasEditor()const override{return true;}
    juce::AudioProcessorEditor* createEditor() override;
    void getStateInformation(juce::MemoryBlock& dest)override{
        auto tree=state.copyState();std::unique_ptr<juce::XmlElement> xml(tree.createXml());copyXmlToBinary(*xml,dest);
    }
    void setStateInformation(const void* data,int size)override{
        std::unique_ptr<juce::XmlElement> xml(getXmlFromBinary(data,size));
        if(xml!=nullptr&&xml->hasTagName(state.state.getType()))state.replaceState(juce::ValueTree::fromXml(*xml));
    }
    juce::AudioProcessorValueTreeState& getParameterState() noexcept { return state; }
private:
    juce::AudioProcessorValueTreeState state;
    std::atomic<float>* mix=nullptr; std::atomic<float>* bypass=nullptr;
    std::atomic<float>* hpEnable=nullptr; std::atomic<float>* hpFreq=nullptr; std::atomic<float>* hpSlope=nullptr;
    std::atomic<float>* lpEnable=nullptr; std::atomic<float>* lpFreq=nullptr; std::atomic<float>* lpSlope=nullptr;
    std::array<std::atomic<float>*,6> freq{},q{},gain{},range{},threshold{},attack{},release{},enabled{};
    std::array<std::array<Biquad,4>,2> highPassFilters{},lowPassFilters{};
    std::array<std::array<Biquad,6>,2> eqFilters{},detFilters{};
    std::array<std::array<float,6>,2> envelopePower{},dynamicGainDb{};
    std::array<float,6> attackCoeff{},releaseCoeff{};
    double sampleRate=48000.0;
};

// Premium machined-metal rotary controls for RDJ F6.
class RDJF6KnobLookAndFeel final : public juce::LookAndFeel_V4 {
public:
    void drawRotarySlider(juce::Graphics& g, int x, int y, int width, int height,
                          float sliderPos, float rotaryStartAngle, float rotaryEndAngle,
                          juce::Slider& slider) override {
        juce::ignoreUnused(slider);
        auto bounds=juce::Rectangle<float>((float)x,(float)y,(float)width,(float)height).reduced(7.0f);
        const float diameter=juce::jmin(bounds.getWidth(),bounds.getHeight()-18.0f);
        auto knob=juce::Rectangle<float>(diameter,diameter).withCentre(
            {bounds.getCentreX(),bounds.getY()+diameter*0.5f+2.0f});
        const float cx=knob.getCentreX(), cy=knob.getCentreY(), radius=diameter*0.5f;
        const float angle=rotaryStartAngle+sliderPos*(rotaryEndAngle-rotaryStartAngle);

        // Outer shadow and brushed-metal bezel.
        g.setColour(juce::Colour(0xaa000000));
        g.fillEllipse(knob.translated(1.5f,3.0f));
        g.setGradientFill(juce::ColourGradient(juce::Colour(0xff687983),knob.getX(),knob.getY(),
                                               juce::Colour(0xff151d22),knob.getRight(),knob.getBottom(),false));
        g.fillEllipse(knob);
        g.setColour(juce::Colour(0xff91a4ad));
        g.drawEllipse(knob.reduced(1.0f),1.0f);

        auto face=knob.reduced(diameter*0.105f);
        g.setGradientFill(juce::ColourGradient(juce::Colour(0xff53636d),face.getX(),face.getY(),
                                               juce::Colour(0xff182127),face.getRight(),face.getBottom(),false));
        g.fillEllipse(face);
        g.setColour(juce::Colour(0xffaab8bf).withAlpha(0.55f));
        g.drawEllipse(face.reduced(1.0f),0.8f);

        // Fine scale marks around the knob.
        for(int i=0;i<=30;++i) {
            const float a=rotaryStartAngle+(rotaryEndAngle-rotaryStartAngle)*(float)i/30.0f;
            const float r1=radius*0.88f, r2=radius*(i%5==0?0.99f:0.94f);
            juce::Point<float> p1(cx+std::sin(a)*r1,cy-std::cos(a)*r1);
            juce::Point<float> p2(cx+std::sin(a)*r2,cy-std::cos(a)*r2);
            g.setColour(i%5==0?juce::Colour(0xffd0dce1):juce::Colour(0xff71828a));
            g.drawLine(p1.x,p1.y,p2.x,p2.y,i%5==0?1.4f:0.8f);
        }

        // Coloured progress arc.
        juce::Path arc;
        arc.addCentredArc(cx,cy,radius*0.98f,radius*0.98f,0.0f,
                          rotaryStartAngle,angle,true);
        g.setColour(juce::Colour(0xff10171b));
        juce::Path baseArc;
        baseArc.addCentredArc(cx,cy,radius*0.98f,radius*0.98f,0.0f,
                              rotaryStartAngle,rotaryEndAngle,true);
        g.strokePath(baseArc,juce::PathStrokeType(3.2f,juce::PathStrokeType::curved,juce::PathStrokeType::rounded));
        g.setColour(juce::Colour(0xffff805b));
        g.strokePath(arc,juce::PathStrokeType(3.8f,juce::PathStrokeType::curved,juce::PathStrokeType::rounded));

        // Bright pointer with a small polished cap.
        const float pointerLen=radius*0.64f;
        juce::Point<float> tip(cx+std::sin(angle)*pointerLen,cy-std::cos(angle)*pointerLen);
        g.setColour(juce::Colour(0xff05090c).withAlpha(0.7f));
        g.drawLine(cx+1.0f,cy+1.0f,tip.x+1.0f,tip.y+1.0f,4.0f);
        g.setColour(juce::Colour(0xfff4fbff));
        g.drawLine(cx,cy,tip.x,tip.y,3.0f);
        g.setColour(juce::Colour(0xffdce8ed));
        g.fillEllipse(cx-3.0f,cy-3.0f,6.0f,6.0f);
    }
};

// Custom RDJ F6 editor: frequency-response graph, six selectable bands,
// per-band dynamics controls and a digital dark interface.
class RDJF6Editor final : public juce::AudioProcessorEditor, private juce::Timer {
public:
    explicit RDJF6Editor(RDJF6Processor& proc)
        : AudioProcessorEditor(proc), processor(proc), state(proc.getParameterState()) {
        // Compact default window matching the requested mixer screenshot.
        // The editor remains resizable for users who prefer a larger view.
        setSize(520, 580);
        setResizable(true, true);
        setResizeLimits(500, 560, 1400, 980);

        title.setText("RDJ F6", juce::dontSendNotification);
        title.setFont(juce::Font(22.0f, juce::Font::bold));
        title.setColour(juce::Label::textColourId, juce::Colour(0xffe6edf2));
        addAndMakeVisible(title);
        subtitle.setText("DYNAMIC EQUALIZER  |  6 FLOATING BANDS", juce::dontSendNotification);
        subtitle.setColour(juce::Label::textColourId, juce::Colour(0xff8da0aa));
        addAndMakeVisible(subtitle);

        preset.setText("A: DEFAULT PRESET", juce::dontSendNotification);
        preset.setJustificationType(juce::Justification::centred);
        preset.setColour(juce::Label::textColourId, juce::Colour(0xffc7d2d9));
        preset.setColour(juce::Label::backgroundColourId, juce::Colour(0xff151a1e));
        preset.setColour(juce::Label::outlineColourId, juce::Colour(0xff39464d));
        addAndMakeVisible(preset);

        masterBypass.setButtonText("BYPASS");
        addAndMakeVisible(masterBypass);
        bypassAttachment = std::make_unique<juce::AudioProcessorValueTreeState::ButtonAttachment>(
            state, "bypass", masterBypass);

        graph.setState(state);
        graph.setSampleRate(processor.getSampleRate()>0.0?processor.getSampleRate():48000.0);
        addAndMakeVisible(graph);

        hpfButton.setButtonText("HPF");
        hpfButton.setColour(juce::ToggleButton::textColourId,juce::Colour(0xffe6edf2));
        addAndMakeVisible(hpfButton);
        hpfEnableAttachment=std::make_unique<juce::AudioProcessorValueTreeState::ButtonAttachment>(
            state,"hpf_enable",hpfButton);
        hpfFreqSlider.setSliderStyle(juce::Slider::LinearHorizontal);
        hpfFreqSlider.setRange(20.0,2000.0,1.0);
        hpfFreqSlider.setSkewFactorFromMidPoint(200.0);
        hpfFreqSlider.setTextBoxStyle(juce::Slider::TextBoxRight,false,64,20);
        addAndMakeVisible(hpfFreqSlider);
        hpfFreqAttachment=std::make_unique<juce::AudioProcessorValueTreeState::SliderAttachment>(
            state,"hpf_freq",hpfFreqSlider);
        hpfSlopeBox.addItemList({"12 dB","24 dB","36 dB","48 dB"},1);
        hpfSlopeBox.setTooltip("High-pass filter slope");
        addAndMakeVisible(hpfSlopeBox);
        hpfSlopeAttachment=std::make_unique<juce::AudioProcessorValueTreeState::ComboBoxAttachment>(
            state,"hpf_slope",hpfSlopeBox);

        lpfButton.setButtonText("LPF");
        lpfButton.setColour(juce::ToggleButton::textColourId,juce::Colour(0xffe6edf2));
        addAndMakeVisible(lpfButton);
        lpfEnableAttachment=std::make_unique<juce::AudioProcessorValueTreeState::ButtonAttachment>(
            state,"lpf_enable",lpfButton);
        lpfFreqSlider.setSliderStyle(juce::Slider::LinearHorizontal);
        lpfFreqSlider.setRange(1000.0,20000.0,1.0);
        lpfFreqSlider.setSkewFactorFromMidPoint(6000.0);
        lpfFreqSlider.setTextBoxStyle(juce::Slider::TextBoxRight,false,70,20);
        addAndMakeVisible(lpfFreqSlider);
        lpfFreqAttachment=std::make_unique<juce::AudioProcessorValueTreeState::SliderAttachment>(
            state,"lpf_freq",lpfFreqSlider);
        lpfSlopeBox.addItemList({"12 dB","24 dB","36 dB","48 dB"},1);
        lpfSlopeBox.setTooltip("Low-pass filter slope");
        addAndMakeVisible(lpfSlopeBox);
        lpfSlopeAttachment=std::make_unique<juce::AudioProcessorValueTreeState::ComboBoxAttachment>(
            state,"lpf_slope",lpfSlopeBox);

        const juce::StringArray bandNames { "1", "2", "3", "4", "5", "6" };
        for (int i=0;i<6;++i) {
            bandButtons[(size_t)i].setButtonText(bandNames[i]);
            bandButtons[(size_t)i].setClickingTogglesState(false);
            bandButtons[(size_t)i].onClick=[this,i]{ selectBand(i); };
            addAndMakeVisible(bandButtons[(size_t)i]);
        }

        const juce::StringArray names { "FREQ (Hz)", "Q", "GAIN (dB)", "RANGE (dB)", "THRESHOLD", "ATTACK (ms)", "RELEASE (ms)" };
        const std::array<float,7> mins {20.0f,0.1f,-18.0f,-18.0f,-60.0f,0.1f,5.0f};
        const std::array<float,7> maxs {20000.0f,18.0f,18.0f,0.0f,0.0f,100.0f,500.0f};
        for(int i=0;i<7;++i) {
            knobLabels[(size_t)i].setText(names[i],juce::dontSendNotification);
            knobLabels[(size_t)i].setJustificationType(juce::Justification::centred);
            knobLabels[(size_t)i].setColour(juce::Label::textColourId,juce::Colour(0xff9eabb2));
            addAndMakeVisible(knobLabels[(size_t)i]);
            auto& sl=knobs[(size_t)i];
            sl.setSliderStyle(juce::Slider::RotaryHorizontalVerticalDrag);
            sl.setTextBoxStyle(juce::Slider::TextBoxBelow,false,70,19);
            sl.setRange(mins[(size_t)i],maxs[(size_t)i],i==0?1.0:0.01);
            sl.setColour(juce::Slider::rotarySliderFillColourId,juce::Colour(0xffff754f));
            sl.setColour(juce::Slider::rotarySliderOutlineColourId,juce::Colour(0xff39464d));
            sl.setColour(juce::Slider::thumbColourId,juce::Colour(0xfff3f5f6));
            sl.setColour(juce::Slider::textBoxTextColourId,juce::Colour(0xffe7edf0));
            sl.setColour(juce::Slider::textBoxBackgroundColourId,juce::Colour(0xff171d21));
            sl.setColour(juce::Slider::textBoxOutlineColourId,juce::Colour(0xff3b474e));
            sl.onValueChange=[this,i]{ if(!updating) writeKnob(i); };
            addAndMakeVisible(sl);
        }

        mixLabel.setText("MIX",juce::dontSendNotification);
        mixLabel.setColour(juce::Label::textColourId,juce::Colour(0xff8e9ba2));
        addAndMakeVisible(mixLabel);
        mixSlider.setRange(0,100,0.1);
        mixSlider.setValue(100);
        mixSlider.setTextBoxStyle(juce::Slider::TextBoxRight,false,52,20);
        mixSlider.onValueChange=[this]{ state.getParameter("mix")->setValueNotifyingHost((float)mixSlider.getValue()/100.0f); };
        addAndMakeVisible(mixSlider);

        for(int i=0;i<6;++i) {
            bandColours[(size_t)i]=juce::Colour::fromHSV((float)i/6.0f,0.78f,0.98f,1.0f);
        }
        selectBand(0);
        startTimerHz(15);
    }

    ~RDJF6Editor() override { stopTimer(); }

    void paint(juce::Graphics& g) override {
        g.fillAll(juce::Colour(0xff101417));
        auto r=getLocalBounds().toFloat().reduced(7.0f);
        g.setColour(juce::Colour(0xff20282d)); g.fillRoundedRectangle(r,5.0f);
        g.setColour(juce::Colour(0xff070a0c)); g.fillRect(juce::Rectangle<float>(10,58,(float)getWidth()-20,1));
        g.setColour(juce::Colour(0xff171e22)); g.fillRect(juce::Rectangle<float>(10,(float)getHeight()-190,(float)getWidth()-20,180));
        g.setColour(juce::Colour(0xff39464d)); g.drawHorizontalLine(getHeight()-190,12.0f,(float)getWidth()-12.0f);
    }

    void resized() override {
        auto area=getLocalBounds().reduced(18);
        auto header=area.removeFromTop(42);
        title.setBounds(header.removeFromLeft(120));
        subtitle.setBounds(header.removeFromLeft(310));
        masterBypass.setBounds(header.removeFromRight(100).reduced(4));
        preset.setBounds(header.reduced(8,5));
        area.removeFromTop(8);
        graph.setBounds(area.removeFromTop((int)(getHeight()*0.43f)));
        area.removeFromTop(4);
        auto filterRow=area.removeFromTop(38);
        auto half=filterRow.getWidth()/2;
        auto hp=filterRow.removeFromLeft(half).reduced(3,2);
        hpfButton.setBounds(hp.removeFromLeft(46));
        hpfSlopeBox.setBounds(hp.removeFromLeft(70));
        hpfFreqSlider.setBounds(hp);
        auto lp=filterRow.reduced(3,2);
        lpfButton.setBounds(lp.removeFromLeft(46));
        lpfSlopeBox.setBounds(lp.removeFromLeft(70));
        lpfFreqSlider.setBounds(lp);
        area.removeFromTop(4);
        auto bandRow=area.removeFromTop(34);
        const int bw=bandRow.getWidth()/6;
        for(int i=0;i<6;++i) bandButtons[(size_t)i].setBounds(bandRow.removeFromLeft(bw).reduced(3,2));
        area.removeFromTop(8);
        auto knobsRow=area.removeFromTop(area.getHeight()-36);
        const int kw=knobsRow.getWidth()/7;
        for(int i=0;i<7;++i){
            auto cell=knobsRow.removeFromLeft(kw).reduced(3,0);
            knobLabels[(size_t)i].setBounds(cell.removeFromTop(22));
            knobs[(size_t)i].setBounds(cell);
        }
        auto footer=area.removeFromBottom(28);
        mixLabel.setBounds(footer.removeFromRight(35));
        mixSlider.setBounds(footer.removeFromRight(150));
    }

private:
    class ResponseGraph final : public juce::Component {
    public:
        void setState(juce::AudioProcessorValueTreeState& s){ state=&s; }
        void setSampleRate(double sr) { sampleRate=juce::jmax(8000.0,sr); repaint(); }
        void paint(juce::Graphics& g) override {
            auto r=getLocalBounds().toFloat();
            g.fillAll(juce::Colour(0xff090d0f));
            const float left=42,right=r.getWidth()-34,top=18,bottom=r.getHeight()-24;
            auto xFor=[&](float hz){return left+(std::log10(juce::jlimit(20.0f,20000.0f,hz)/20.0f)/3.0f)*(right-left);};
            auto yFor=[&](float db){return top+((18.0f-db)/36.0f)*(bottom-top);};
            g.setColour(juce::Colour(0xff202a30));
            for(int db=-18;db<=18;db+=3){
                float y=yFor((float)db); g.drawHorizontalLine((int)y,left,right);
                g.setColour(juce::Colour(0xff75828a)); g.setFont(10.0f);
                g.drawText(juce::String(db),2,(int)y-7,32,14,juce::Justification::right);
                g.setColour(juce::Colour(0xff202a30));
            }
            const float freqs[]={20,32,63,125,250,500,1000,2000,4000,8000,16000};
            for(float f:freqs){
                float x=xFor(f); g.drawVerticalLine((int)x,top,bottom);
                g.setColour(juce::Colour(0xff85929a)); g.setFont(10.0f);
                juce::String label=f>=1000?juce::String(f/1000.0f, f>=10000?0:1)+"k":juce::String((int)f);
                g.drawText(label,(int)x-18,(int)bottom+4,36,14,juce::Justification::centred);
                g.setColour(juce::Colour(0xff202a30));
            }
            g.setColour(juce::Colour(0xff8c9aa1)); g.drawLine(left,yFor(0),right,yFor(0),1.2f);
            if(state==nullptr)return;
            // Draw the actual static magnitude response of the same RBJ biquads
            // used by the processor. This avoids the old approximate roll-off,
            // which could show an LPF curve in the wrong direction.
            auto magnitudeDb = [](double hz, double sr, double b0, double b1, double b2,
                                  double a1, double a2) -> double {
                const double w = juce::MathConstants<double>::twoPi * hz / sr;
                const double c1 = std::cos(w), s1 = std::sin(w);
                const double c2 = std::cos(2.0*w), s2 = std::sin(2.0*w);
                const double nr = b0 + b1*c1 + b2*c2;
                const double ni = -b1*s1 - b2*s2;
                const double dr = 1.0 + a1*c1 + a2*c2;
                const double di = -a1*s1 - a2*s2;
                const double den = dr*dr + di*di;
                const double mag2 = (nr*nr + ni*ni) / juce::jmax(1.0e-24, den);
                return 20.0 * std::log10(juce::jmax(1.0e-12, std::sqrt(mag2)));
            };
            auto makeCut = [](double sr, double f, bool highPass, double sectionQ,
                              double& b0, double& b1, double& b2, double& a1, double& a2) {
                f = juce::jlimit(10.0, sr*0.475, f);
                const double w=juce::MathConstants<double>::twoPi*f/sr;
                const double c=std::cos(w), sn=std::sin(w);
                const double alpha=sn/(2.0*juce::jmax(0.1,sectionQ)), a0=1.0+alpha;
                if(highPass) {
                    b0=((1.0+c)*0.5)/a0; b1=-(1.0+c)/a0; b2=b0;
                } else {
                    b0=((1.0-c)*0.5)/a0; b1=(1.0-c)/a0; b2=b0;
                }
                a1=(-2.0*c)/a0; a2=(1.0-alpha)/a0;
            };
            static constexpr double sectionQs[4][4] = {
                {0.7071067812,0.7071067812,0.7071067812,0.7071067812},
                {1.306562965,0.5411961001,0.7071067812,0.7071067812},
                {1.931851653,0.7071067812,0.5176380902,0.7071067812},
                {2.562915448,0.9009688679,0.6013448872,0.5097955791}
            };
            const double graphSampleRate = sampleRate;
            const bool hpOn=state->getRawParameterValue("hpf_enable")->load()>=0.5f;
            const bool lpOn=state->getRawParameterValue("lpf_enable")->load()>=0.5f;
            const double hpHz=state->getRawParameterValue("hpf_freq")->load();
            const double lpHz=state->getRawParameterValue("lpf_freq")->load();
            const int hpStages=juce::jlimit(1,4,(int)std::lround(state->getRawParameterValue("hpf_slope")->load())+1);
            const int lpStages=juce::jlimit(1,4,(int)std::lround(state->getRawParameterValue("lpf_slope")->load())+1);
            juce::Path response;
            for(int px=0;px<300;++px){
                const double hz=20.0*std::pow(1000.0,(double)px/299.0);
                double db=0.0;
                double b0,b1,b2,a1,a2;
                if(hpOn) for(int stage=0;stage<hpStages;++stage) {
                    makeCut(graphSampleRate,hpHz,true,sectionQs[hpStages-1][stage],b0,b1,b2,a1,a2);
                    db+=magnitudeDb(hz,graphSampleRate,b0,b1,b2,a1,a2);
                }
                if(lpOn) for(int stage=0;stage<lpStages;++stage) {
                    makeCut(graphSampleRate,lpHz,false,sectionQs[lpStages-1][stage],b0,b1,b2,a1,a2);
                    db+=magnitudeDb(hz,graphSampleRate,b0,b1,b2,a1,a2);
                }
                for(int b=0;b<6;++b){
                    const juce::String n=juce::String(b);
                    const double f=state->getRawParameterValue("freq"+n)->load();
                    const double qq=juce::jmax(0.1f,state->getRawParameterValue("q"+n)->load());
                    const double gain=state->getRawParameterValue("gain"+n)->load();
                    const double fc=juce::jlimit(20.0,graphSampleRate*0.45,f);
                    const double A=std::pow(10.0,gain/40.0);
                    const double w=juce::MathConstants<double>::twoPi*fc/graphSampleRate;
                    const double c=std::cos(w), sn=std::sin(w);
                    const double alpha=sn/(2.0*qq), a0=1.0+alpha/A;
                    b0=(1.0+alpha*A)/a0; b1=(-2.0*c)/a0; b2=(1.0-alpha*A)/a0;
                    a1=(-2.0*c)/a0; a2=(1.0-alpha/A)/a0;
                    db+=magnitudeDb(hz,graphSampleRate,b0,b1,b2,a1,a2);
                }
                db=(double)juce::jlimit(-18.0,18.0,db);
                const float x=left+(right-left)*(float)px/299.0f, y=yFor((float)db);
                if(px==0)response.startNewSubPath(x,y);else response.lineTo(x,y);
            }
            g.setColour(juce::Colour(0xffa7b4ba)); g.strokePath(response,juce::PathStrokeType(1.8f));
            for(int b=0;b<6;++b){
                float f=state->getRawParameterValue("freq"+juce::String(b))->load();
                float db=state->getRawParameterValue("gain"+juce::String(b))->load();
                float x=xFor(f),y=yFor(db);
                auto c=juce::Colour::fromHSV((float)b/6.0f,0.78f,0.98f,1.0f);
                g.setColour(c); g.drawEllipse(x-11,y-11,22,22,2.0f);
                g.fillEllipse(x-2.5f,y-2.5f,5,5);
                g.setFont(12.0f); g.drawText(juce::String(b+1),(int)x-8,(int)y-8,16,16,juce::Justification::centred);
            }
        }
        void mouseDown(const juce::MouseEvent& e) override { drag(e); }
        void mouseDrag(const juce::MouseEvent& e) override { drag(e); }
    private:
        void drag(const juce::MouseEvent& e){
            if(state==nullptr)return;
            const float left=42,right=(float)getWidth()-34,top=18,bottom=(float)getHeight()-24;
            int best=0; float bestD=1.0e9f;
            for(int b=0;b<6;++b){
                float f=state->getRawParameterValue("freq"+juce::String(b))->load();
                float db=state->getRawParameterValue("gain"+juce::String(b))->load();
                float x=left+(std::log10(juce::jlimit(20.0f,20000.0f,f)/20.0f)/3.0f)*(right-left);
                float y=top+((18.0f-db)/36.0f)*(bottom-top);
                float d=std::hypot(x-e.position.x,y-e.position.y);
                if(d<bestD){bestD=d;best=b;}
            }
            if(bestD>42.0f)return;
            float norm=juce::jlimit(0.0f,1.0f,(e.position.x-left)/(right-left));
            float hz=20.0f*std::pow(1000.0f,norm);
            float db=juce::jlimit(-18.0f,18.0f,18.0f-36.0f*(e.position.y-top)/(bottom-top));
            auto* fp=state->getParameter("freq"+juce::String(best));
            auto* gp=state->getParameter("gain"+juce::String(best));
            fp->setValueNotifyingHost(fp->convertTo0to1(hz));
            gp->setValueNotifyingHost(gp->convertTo0to1(db));
            repaint();
        }
        juce::AudioProcessorValueTreeState* state=nullptr;
        double sampleRate=48000.0;
    };

    void selectBand(int b){
        selectedBand=juce::jlimit(0,5,b);
        for(int i=0;i<6;++i){
            bandButtons[(size_t)i].setColour(juce::TextButton::buttonColourId,
                i==selectedBand?bandColours[(size_t)i].withAlpha(0.28f):juce::Colour(0xff171d21));
            bandButtons[(size_t)i].setColour(juce::TextButton::textColourOffId,
                i==selectedBand?bandColours[(size_t)i]:juce::Colour(0xffaab6bc));
        }
        updating=true;
        const auto n=juce::String(selectedBand);
        const juce::String ids[7]={"freq","q","gain","range","threshold","attack","release"};
        for(int i=0;i<7;++i)knobs[(size_t)i].setValue(state.getRawParameterValue(ids[i]+n)->load(),juce::dontSendNotification);
        updating=false;
        graph.repaint();
    }
    void writeKnob(int i){
        const juce::String ids[7]={"freq","q","gain","range","threshold","attack","release"};
        auto* p=state.getParameter(ids[i]+juce::String(selectedBand));
        if(p!=nullptr)p->setValueNotifyingHost(p->convertTo0to1((float)knobs[(size_t)i].getValue()));
        graph.repaint();
    }
    void timerCallback() override {
        if(!updating){
            const float v=state.getRawParameterValue("mix")->load();
            if(!mixSlider.isMouseButtonDown())mixSlider.setValue(v,juce::dontSendNotification);
        }
        graph.setSampleRate(processor.getSampleRate()>0.0?processor.getSampleRate():48000.0);
        graph.repaint();
    }

    RDJF6Processor& processor;
    juce::AudioProcessorValueTreeState& state;
    juce::Label title,subtitle,preset,mixLabel;
    juce::ToggleButton masterBypass,hpfButton,lpfButton;
    juce::ComboBox hpfSlopeBox,lpfSlopeBox;
    juce::Slider mixSlider,hpfFreqSlider,lpfFreqSlider;
    ResponseGraph graph;
    RDJF6KnobLookAndFeel knobLook;
    std::array<juce::TextButton,6> bandButtons;
    std::array<juce::Label,7> knobLabels;
    std::array<juce::Slider,7> knobs;
    std::array<juce::Colour,6> bandColours;
    std::unique_ptr<juce::AudioProcessorValueTreeState::ButtonAttachment> bypassAttachment;
    std::unique_ptr<juce::AudioProcessorValueTreeState::ButtonAttachment> hpfEnableAttachment,lpfEnableAttachment;
    std::unique_ptr<juce::AudioProcessorValueTreeState::SliderAttachment> hpfFreqAttachment,lpfFreqAttachment;
    std::unique_ptr<juce::AudioProcessorValueTreeState::ComboBoxAttachment> hpfSlopeAttachment,lpfSlopeAttachment;
    int selectedBand=0;
    bool updating=false;
};

juce::AudioProcessorEditor* RDJF6Processor::createEditor(){ return new RDJF6Editor(*this); }

// Dedicated hardware-style fader rendering for the GEQ editor.
class RDJGeqLookAndFeel final : public juce::LookAndFeel_V4 {
public:
    void drawLinearSlider(juce::Graphics& g, int x, int y, int width, int height,
                          float sliderPos, float minSliderPos, float maxSliderPos,
                          const juce::Slider::SliderStyle style, juce::Slider& slider) override {
        juce::ignoreUnused(minSliderPos, maxSliderPos);
        if (style != juce::Slider::LinearVertical) {
            juce::LookAndFeel_V4::drawLinearSlider(g, x, y, width, height,
                sliderPos, minSliderPos, maxSliderPos, style, slider);
            return;
        }
        auto area = juce::Rectangle<float>((float)x, (float)y, (float)width, (float)height);
        const float trackW = 5.0f;
        auto track = juce::Rectangle<float>(area.getCentreX() - trackW * 0.5f,
            area.getY() + 5.0f, trackW, juce::jmax(1.0f, area.getHeight() - 10.0f));
        g.setColour(juce::Colour(0xff101923));
        g.fillRoundedRectangle(track, 2.5f);
        g.setColour(juce::Colour(0xff16c9ec).withAlpha(0.35f));
        g.fillRoundedRectangle(track.withWidth(1.0f).withX(track.getCentreX() - 0.5f), 1.0f);

        const float capW = juce::jmin(area.getWidth() - 2.0f, 25.0f);
        const float capH = 17.0f;
        auto cap = juce::Rectangle<float>(capW, capH).withCentre(
            { area.getCentreX(), juce::jlimit(area.getY() + capH * 0.5f,
                area.getBottom() - capH * 0.5f, sliderPos) });
        g.setColour(juce::Colour(0x99000000));
        g.fillRoundedRectangle(cap.translated(1.0f, 1.5f), 3.0f);
        g.setGradientFill(juce::ColourGradient(juce::Colour(0xfff5fbff),
            cap.getX(), cap.getY(), juce::Colour(0xff8298a8),
            cap.getX(), cap.getBottom(), false));
        g.fillRoundedRectangle(cap, 3.0f);
        g.setColour(juce::Colour(0xffd8f4ff));
        g.drawRoundedRectangle(cap.reduced(0.5f), 3.0f, 0.8f);
        g.setColour(juce::Colour(0xff536b7a));
        g.drawHorizontalLine((int)cap.getCentreY(), cap.getX() + 3.0f, cap.getRight() - 3.0f);
    }
};

// Custom RDJ GEQ editor: 31 vertical faders with frequency labels and response display.
class RDJGeqEditor final : public juce::AudioProcessorEditor,
                           private juce::Button::Listener {
public:
    explicit RDJGeqEditor(RDJGeqProcessor& p)
        : AudioProcessorEditor(p), processor(p) {
        setSize(1240, 410);
        setResizable(true, true);
        setResizeLimits(1080, 370, 1600, 560);

        for (int i = 0; i < RDJGeqProcessor::bandCount; ++i) {
            auto& slider = sliders[(size_t)i];
            slider.setLookAndFeel(&geqLookAndFeel);
            slider.setSliderStyle(juce::Slider::LinearVertical);
            slider.getProperties().set("faderSkin", "silver");
            slider.setTextBoxStyle(juce::Slider::TextBoxBelow, false, 42, 18);
            slider.setRange(-12.0, 12.0, 0.1);
            slider.setNumDecimalPlacesToDisplay(1);
            slider.setColour(juce::Slider::trackColourId, juce::Colour(0xff13c9ed));
            slider.setColour(juce::Slider::thumbColourId, juce::Colour(0xffe7f7ff));
            slider.setColour(juce::Slider::textBoxTextColourId, juce::Colours::white);
            slider.setColour(juce::Slider::textBoxBackgroundColourId, juce::Colour(0xff17232d));
            slider.setColour(juce::Slider::textBoxOutlineColourId, juce::Colour(0xff405361));
            addAndMakeVisible(slider);
            attachments[(size_t)i] = std::make_unique<juce::AudioProcessorValueTreeState::SliderAttachment>(
                processor.getParameterState(), "band" + juce::String(i), slider);

            frequencyLabels[(size_t)i].setText(formatFrequency(RDJGeqProcessor::frequencies[(size_t)i]),
                                                juce::dontSendNotification);
            frequencyLabels[(size_t)i].setJustificationType(juce::Justification::centred);
            frequencyLabels[(size_t)i].setFont(juce::Font(10.0f));
            frequencyLabels[(size_t)i].setColour(juce::Label::textColourId, juce::Colour(0xffc5d5df));
            addAndMakeVisible(frequencyLabels[(size_t)i]);
        }

        bypass.setButtonText("BYPASS");
        bypass.setColour(juce::ToggleButton::textColourId, juce::Colours::white);
        addAndMakeVisible(bypass);
        bypassAttachment = std::make_unique<juce::AudioProcessorValueTreeState::ButtonAttachment>(
            processor.getParameterState(), "bypass", bypass);

        resetButton.setButtonText("RESET");
        resetButton.addListener(this);
        addAndMakeVisible(resetButton);
        title.setText("RDJ GEQ 31 BAND", juce::dontSendNotification);
        title.setFont(juce::Font(20.0f, juce::Font::bold));
        title.setColour(juce::Label::textColourId, juce::Colour(0xff20d9ff));
        addAndMakeVisible(title);
        subtitle.setText("-12 dB                                  0 dB                                  +12 dB",
                         juce::dontSendNotification);
        subtitle.setColour(juce::Label::textColourId, juce::Colour(0xff9eb4c2));
        addAndMakeVisible(subtitle);
    }

    ~RDJGeqEditor() override { resetButton.removeListener(this); for (auto& slider : sliders) slider.setLookAndFeel(nullptr); }

    void paint(juce::Graphics& g) override {
        g.fillAll(juce::Colour(0xff101820));
        auto area = getLocalBounds().toFloat();
        g.setColour(juce::Colour(0xff1c2b36));
        g.fillRoundedRectangle(area.reduced(8.0f), 10.0f);

        auto graph = juce::Rectangle<float>(24.0f, 74.0f,
            (float)getWidth() - 48.0f, (float)getHeight() - 180.0f);
        g.setColour(juce::Colour(0xff263b49));
        g.fillRoundedRectangle(graph, 5.0f);

        for (int db = -12; db <= 12; db += 3) {
            const float y = graph.getCentreY() - (float)db / 24.0f * graph.getHeight();
            g.setColour(db == 0 ? juce::Colour(0xff8da9b8) : juce::Colour(0xff405462));
            g.drawHorizontalLine((int)y, graph.getX() + 5.0f, graph.getRight() - 5.0f);
            g.setFont(10.0f);
            g.drawText(juce::String(db), 3, (int)y - 7, 20, 14, juce::Justification::centredRight);
        }

        juce::Path response;
        const float left = graph.getX() + 18.0f;
        const float usable = graph.getWidth() - 36.0f;
        for (int i = 0; i < RDJGeqProcessor::bandCount; ++i) {
            const float x = left + usable * (float)i / (RDJGeqProcessor::bandCount - 1);
            const float db = sliders[(size_t)i].getValue();
            const float y = graph.getCentreY() - db / 24.0f * graph.getHeight();
            if (i == 0) response.startNewSubPath(x, y); else response.lineTo(x, y);
        }
        g.setColour(juce::Colour(0xff14d7ff));
        g.strokePath(response, juce::PathStrokeType(2.0f));
    }

    void resized() override {
        auto bounds = getLocalBounds().reduced(18);
        auto header = bounds.removeFromTop(42);
        title.setBounds(header.removeFromLeft(300));
        resetButton.setBounds(header.removeFromRight(88).reduced(2));
        bypass.setBounds(header.removeFromRight(110).reduced(2));
        subtitle.setBounds(bounds.removeFromBottom(24));
        bounds.removeFromBottom(5);
        const int labelHeight = 22;
        const int sliderWidth = juce::jmax(22, bounds.getWidth() / RDJGeqProcessor::bandCount);
        for (int i = 0; i < RDJGeqProcessor::bandCount; ++i) {
            auto col = bounds.removeFromLeft(sliderWidth);
            sliders[(size_t)i].setBounds(col.withTrimmedTop(10).withTrimmedBottom(labelHeight + 18));
            frequencyLabels[(size_t)i].setBounds(col.withY(getHeight() - 56).withHeight(labelHeight));
        }
    }

private:
    static juce::String formatFrequency(double hz) {
        if (hz >= 1000.0) return juce::String(hz / 1000.0, hz >= 10000.0 ? 0 : 1) + "k";
        return juce::String((int)hz);
    }
    void buttonClicked(juce::Button* b) override {
        if (b == &resetButton) {
            for (int i = 0; i < RDJGeqProcessor::bandCount; ++i)
                processor.getParameterState().getParameter("band" + juce::String(i))->setValueNotifyingHost(0.5f);
            repaint();
        }
    }

    RDJGeqProcessor& processor;
    RDJGeqLookAndFeel geqLookAndFeel;
    std::array<juce::Slider, RDJGeqProcessor::bandCount> sliders;
    std::array<juce::Label, RDJGeqProcessor::bandCount> frequencyLabels;
    std::array<std::unique_ptr<juce::AudioProcessorValueTreeState::SliderAttachment>,
               RDJGeqProcessor::bandCount> attachments;
    juce::ToggleButton bypass;
    juce::TextButton resetButton;
    juce::Label title, subtitle;
    std::unique_ptr<juce::AudioProcessorValueTreeState::ButtonAttachment> bypassAttachment;
};

juce::AudioProcessorEditor* RDJGeqProcessor::createEditor() {
    return new RDJGeqEditor(*this);
}

// Plugin editor windows stay owned by the mixer insert. Closing the window
